\label{THM-PS-L2-Regularity}
\label{Phong-Stein-Thm}{{\rm(\cite{PS1997})}}
If $S$ is a real-valued and real-analytic function near $(0,0)$, then
\begin{equation*}
\|Rf\|_{L^2_{\delta/2}}\leq C \|f\|_{L^2},
\end{equation*}
where $(\frac1{\delta},\frac1{\delta})$ is the intersection of $y=x$ and the reduced Newton polyhedron $N_r(S)$ of $S$.

{\rm(\cite{lee})}
If $S$ is real analytic near $(0,0)$, then
\begin{equation*}
\|Rf\|_{   L^{\frac{m+n+1}{m}} (\Bbb R^2) }
\leq C \|f\|_{ L^{\frac{m+n+1}{m+1}} (\Bbb R^2) },
\end{equation*}
where $(m,n)$ is an extreme point of $N_r(S)$.

\label{Main-Thm-1}
Assume $S$ is a real-valued real analytic function near the origin in $\Bbb R^2$. Let $N_r(S)$ be the reduced Newton polyhedron of $S$. Then the following statements are true.
\vspace{0.5 \baselineskip}

\noindent {\rm(i)} If $(m,n)$ is an extreme point of $N_r(S)$, then the critical $L^p$ Sobolev regularity
\begin{equation*}
\|Rf\|_{L^p_\delta}\lesssim \|f\|_{L^p},~~~p=\frac{m+n}{m},~~~\delta=\frac{1}{m+n},
\end{equation*}
holds for $\varphi\in C_0^{\infty}(\mathbb{R}^3)$ satisfying $\varphi(0,0,0)\neq 0$ if and only if $m=n$.\\
\noindent {\rm(ii)} Let $(A_L,B_L)$ be the leftmost extreme point of $N_r(S)$. If $A_L>B_L$ and $\varphi(0,0,0)\neq 0$, then there is no constant $C>0$ such that the Sobolev regularity
\begin{equation*}
\left\|
|\partial_t|^{\delta}Rf
\right\|_{L^p}
\leq
C\|f\|_{L^p},~~~f\in C_0^{\infty},
\end{equation*}
holds for a pair of exponents $(p,\delta)$ satisfying
$$\frac{A_L+B_L}{A_L}\leq p <2,~~~\delta=\frac{1}{A_L}\cdot\frac{1}{p}.$$

\noindent {\rm(iii)} Let $(A_R,B_R)$ be the rightmost extreme point of $N_r(S)$. If $A_R<B_R$ and $\varphi(0,0,0)\neq 0$, then there is no constant $C>0$ such that for all
$f\in C_0^{\infty}$ the following inequality
\begin{equation*}
\left\|
|\partial_t|^{\delta}Rf
\right\|_{L^p}
\leq
C\|f\|_{L^p}
\end{equation*}
is true for a pair $(p,\delta)$ satisfying
\begin{equation*}
2<p\leq \frac{A_R+B_R}{A_R},~~~
\delta=\frac{1}{B_R}\cdot
\left(1-\frac{1}{p}\right).
\end{equation*}

\label{Main-Thm-2}
Assume $S$ is a real-valued real analytic function near the origin. Let $N_r(S)$ be the reduced Newton polyhedron of $S$. The leftmost and rightmost extreme points of $N_r(S)$ are denoted by $(A_L,B_L)$ and $(A_R,B_R)$, respectively. Suppose $(m,n)$ is a point on the boundary $\partial N_r(S)$ of $N_r(S)$. Then there exists a constant $C$ such that
\begin{equation*}
\|Rf\|_{L^p_{\alpha}}\leq C\|f\|_{L^p},~~~p=\frac{m+n}{m},
~~~\alpha=\frac{1}{m+n},
\end{equation*}
for all $f\in C_0^{\infty}$ provided that one of the following conditions is true.
\vspace{0.5 \baselineskip}

\noindent{\rm (i)} $A_L<m<A_R$ and $(m,n)$ is not an extreme point of $N_r(S)$.\\
\noindent{\rm (ii)} $(m,n)$ is an extreme point of $N_r(S)$ and $m=n$.\\
\noindent{\rm (iii)} $m\leq A_L$ and $\frac{m+n}{m}\geq2$.\\
\noindent{\rm (iv)} $m\geq A_R$ and $\frac{m+n}{m}\leq 2$.

\label{Def-fractional-Sobolev}
Assume $1<p<\infty$ and $s>0$. For $f\in \mathcal{S}(\Bbb R^n)$,
\begin{equation*}
\|f\|_{L^{p}_s}=\|f\|_{L^p}
+
\sum_{k=1}^{n}\Big\| |\partial_k|^sf \Big\|_{L^p}.
\end{equation*}
Then $L^p_s(\Bbb R^n)$ is the completion of $\mathcal{S}(\Bbb R^n)$ in the norm $\|\cdot\|_{L^{p}_s}$.

\label{Kato-Ponce-ineq}
Assume $1<p<\infty$ and $s>0$. Then there exists a constant $C$ such that
\begin{equation*}
\Big\||\partial_t|^{s}(fg)\Big\|_{L^p(\Bbb R^2)}
\leq C
\left[\Big\||\partial_t|^{s}f\Big\|_{L^p(\Bbb R^2)}
\|g\|_{L^{\infty}}
+
\Big\||\partial_t|^{s}g\Big\|_{L^p(\Bbb R^2)}
\|f\|_{L^{\infty}}\right],
\end{equation*}
where $(t,x)\in\Bbb R^2$ and $f,g$ are Schwartz functions in $\Bbb R^2$.

\label{Thm-Failure-Extreme-Points}
Assume $S$ is a real-valued real analytic function near the origin, and $S(0,0)=0$. If $(m,n)$ is an extreme point of $N_r(S)$ with $m\neq n$, then there is no constant $C$ such that
$$\|Rf\|_{L^{\frac{m+n}{m}}_{\frac{1}{m+n}}(\Bbb R^2)}
\leq C\|f\|_{L^\frac{m+n}{m}(\Bbb R^2)},~~~f\in C_0^{\infty}(\Bbb R^2).$$

\label{Main-Theorem-Full-Range}
Assume $(m,n)$ is a vertex of $N_r(S)$ with $m,n\geq 1$. If $Rf$ is bounded from $L^{\frac{m+n}{m}}(\Bbb R^2)$ into $L^{\frac{m+n}{m}}_{\frac{1}{m+n}}(\Bbb R^2)$ for any cut-off function $\varphi\in C_0^{\infty}(\Bbb R^3)$, $\varphi(0)\neq 0$, supported in a sufficiently small neighborhood of the origin, then
$$\left\| |\partial_t|^{\frac{1}{m+n} } R_{m,n}f \right\|_{\frac{m+n}{m}}
\leq
C \left\| f \right\|_{\frac{m+n}{m}}$$
for some constant $C$ and any $f\in C_0^{\infty}$.

Without loss of generality, we assume that $S(x,0)$ and $S(0,y)$ vanish identically. Then $N_r(S)=N(S)$. Let $\varphi\in C_0^{\infty}(\Bbb R^3)$ with $\varphi(0)\neq 0$. For $\overrightarrow{\mu}=(\mu_1,\mu_2)$ with $\mu_1,\mu_2>0$. For any $f\in C_0^{\infty}(\Bbb R^2)$, we write $f_{\overrightarrow{\mu}}(t,x)=f(\mu_1t,\mu_2x)$. The definition of Radon transform $R$ gives
\begin{equation*}
Rf_{\overrightarrow{\mu}}(t,x)
=
\int_{-\infty}^{\infty}
f(\mu_1t + \mu_1 S(x,y),\mu_2y)
\varphi(t,x,y)dy.
\end{equation*}
For $\mu_3>0$, consider
\begin{equation*}
G(t,x)
=
\int_{-\infty}^{\infty}
f\big(t + \mu_1 S(x/\mu_3,y/\mu_2),y\big)
\varphi(t/\mu_1,x/\mu_3,y/\mu_2)dy.
\end{equation*}
Then we see that
$Rf_{\overrightarrow{\mu}}(t,x)
=
\mu_2^{-1}G(\mu_1t,\mu_3x).
$
For fixed positive numbers $\mu_1,\mu_2,\mu_3$, it follows from the assumption $f\in C_0^{\infty}$ that both $Rf_{\overrightarrow{\mu}}$ and $G$ are smooth with compact support. On the other hand, for $\delta>0$,
\begin{equation*}
|\partial_t|^{\delta}\left( Rf_{\overrightarrow{\mu}}(t,x) \right)
=
\mu_1^{\delta}\mu_2^{-1}
(|\partial_t|^{\delta}G)
(\mu_1t, \mu_3x).
\end{equation*}
By the inverse Fourier transform, one can see that
\begin{eqnarray}\label{inverseFT-FD-G}
& &
|\partial_t|^{\delta}G(t, x) \nonumber \\
&=&
\int_{\Bbb R^3}
e^{2\pi i t\xi}(2\pi|\xi|)^{\delta}
e^{2\pi i \eta \mu_1 S(\frac{x}{\mu_3},\frac{y}{\mu_2})}
(\mathcal{F}_1f)(\eta,y)~
\mu_1(\mathcal{F}_1\varphi)
 \Big(\mu_1(\xi-\eta),\frac{x}{\mu_3},\frac{y}{\mu_2}\Big)
d\eta dy d\xi.~~~
\end{eqnarray}
Since $(m,n)$ is an extreme point of the Newton polyhedron $N(S)$, we can take a line
$L:\alpha x+ \beta y=1$ in the plane, $\alpha>0$, $\beta>0$, such that $(m,n)\in L$ and $\alpha k+ \beta l>1$ for any point $(k,l)\in N(S)\backslash \{(m,n)\}$.

Take $\mu_1=\tau$, $\mu_2=\tau^{\beta}$, and $\mu_3=\tau^{\alpha}$ with $\tau\geq 1$. We are going to prove
\begin{equation}\label{limit-of-FD}
\lim_{\tau\rightarrow \infty}
|\partial_t|^{\delta}G(t, x)
=
c|\partial_t|^{\delta}
\left(
\int_{\Bbb R}f(t+a_{m,n}x^my^n,y)dy
\right)
\end{equation}
for all $f\in C_0^{\infty}$, where $c=\varphi(0,0,0)\neq 0$ and $a_{m,n}=\frac{\partial_x^m\partial_y^nS(0,0)}{m!n!}\neq 0$.

To show (\ref{limit-of-FD}), we first prove that the integral (\ref{inverseFT-FD-G}) with respect to $\eta$ is dominated by an integral function in $\xi,y$. More precisely, it is true that
\begin{eqnarray}\label{DM-Functions}
& &\sup
\left|
\int_{\Bbb R}
e^{2\pi i t\xi}(2\pi|\xi|)^{\delta}
e^{2\pi i \eta \mu_1 S(\frac{x}{\mu_3},\frac{y}{\mu_2})}
(\mathcal{F}_1f)(\eta,y)~
\mu_1(\mathcal{F}_1\varphi)
 \Big(\mu_1(\xi-\eta),\frac{x}{\mu_3},\frac{y}{\mu_2}\Big)
d\eta
\right|\nonumber \\
&\leq &
C\frac{|\xi|^{\delta}}{(1+\xi^2)(1+y^2)},
\end{eqnarray}
where the supremum is taken over $\mu_1\geq 1,\mu_2>,\mu_3>0$, and the constant $C$ is independent of $t$, $\xi$, and $y$.
It is clear that $|(\mathcal{F}_1f)(\eta,y)|\lesssim (1+\eta^2)^{-1}(1+y^2)^{-1}$ and $|(\mathcal{F}_1\varphi)(\eta,x,y)|\lesssim (1+\eta^2)^{-1}$. Then the left side of (\ref{DM-Functions}) is bounded by
\begin{eqnarray*}
& &
(2\pi|\xi|)^{\delta}
\sup_{\mu_1\geq 1}
\int_{\Bbb R}
\Big|(\mathcal{F}_1f)(\eta,y)\Big|
\left|\mu_1(\mathcal{F}_1\varphi)
\Big(\mu_1(\xi-\eta),\frac{x}{\mu_3},\frac{y}{\mu_2}\Big)\right|
d\eta\\
&\lesssim&
(2\pi|\xi|)^{\delta}
\sup_{\mu_1\geq 1}
\int_{\Bbb R}
\left(1+\eta^2\right)^{-1}\left(1+y^2\right)^{-1}
\mu_1\left(1+\mu_1^2|\xi-\eta|^2\right)d\eta.
\end{eqnarray*}
To prove (\ref{DM-Functions}), it suffices to show
\begin{equation*}
\sup_{\mu_1\geq 1}
\int_{\Bbb R}
\left( 1+ \eta^2\right)^{-1}
~\mu_1\left( 1+ \mu_1^2|\xi-\eta|^2\right)^{-1}d\eta
\lesssim
\left( 1+ \xi^2 \right)^{-1}.
\end{equation*}
Observe that the Fourier transform of $(1+x^2)^{-1}$ is $\pi e^{-2\pi|\xi|}$. Hence we obtain
\begin{equation*}
\int_{\Bbb R}
\left( 1+ \eta^2\right)^{-1}
~\mu_1\left( 1+ \mu_1^2|\xi-\eta|^2\right)^{-1}d\eta
=\pi\lambda(1+|\lambda \xi|^2)^{-1},~~~\lambda=(1+\mu_1^{-1})^{-1}.
\end{equation*}
Since $\frac12\leq \lambda \leq1$ is true for $\mu_1\geq 1$, the desired estimate follows. It should be pointed out that the above integral identity is not essential in our estimate. For large $\xi$, we can obtain the desired estimate by dividing the above integral into three parts $|\eta|\leq |\xi|/2$, $|\eta|\lesssim |\xi|$, and $|\eta|\geq 2|\xi|$. The details are omitted here. Hence the proof of (\ref{DM-Functions}) is complete.

On the other hand, for fixed $x,y$ and $f\in C_0^{\infty}$, it is clear that
\begin{eqnarray}\label{pointwise-limit}
\color{blue}& &
\lim_{\tau\rightarrow \infty}
\int_{\Bbb R}
e^{2\pi i \eta \tau S(\frac{x}{\tau^{\alpha}},\frac{y}{\tau^{\beta}})}
(\mathcal{F}_1f)(\eta,y)~
\tau(\mathcal{F}_1\varphi)
 \Big(\tau(\xi-\eta),\frac{x}{\tau^{\alpha}},
 \frac{y}{\tau^{\beta}}\Big)
{d\eta }   \nonumber\\
&&
=
ce^{2\pi i a_{m,n}\xi x^m y^n}
(2\pi|\xi|)^{\delta}
(\mathcal{F}_1f)(\xi,y),
\end{eqnarray}
where $c$ and $a_{m,n}$ are given below (\ref{limit-of-FD}).

By the Lebesgue dominated convergence theorem, we obtain
\begin{eqnarray*}
\lim_{\tau\rightarrow\infty}
|\partial_t|^{ \frac1{m+n} }G(t,x)
&=&
c\int_{\Bbb R^2}
e^{2\pi i t\xi}
(2\pi|\xi|)^{\frac1{m+n}}
e^{2\pi i a_{m,n} \xi x^m y^n}
(\mathcal{F}_1f)(\xi,y)dyd\xi\\
&=&
c|\partial_t|^{ \frac1{m+n} }
\left(\int_{\Bbb R}f(t+a_{m,n} x^m y^n,y)dy\right).
\end{eqnarray*}
By a simple scaling argument, we are able to prove the statement of the theorem.

\label{Main-Theorem}
Assume $m\geq 2$ and $n=1$. Then there is {\bf no} constant $C$ such that
$$\left\| |\partial_t|^{\frac{1}{m+1} } R_{m,1}f \right\|_{\frac{m+1}{m}}
\leq
C \left\| f \right\|_{\frac{m+1}{m}}$$
for all $f\in C_0^{\infty}$.

The proof of this useful theorem will be divided into several lemmas. Our argument here was inspired by Christ's original idea in \cite{christ}. { It seems that for any given $\delta\geq 0$ and positive integers $m,n$, there is no constant $C>0$ such that
$$\left\| |\partial_t|^{\delta} R_{m,n}f \right\|_{\frac{m+1}{m}}
\leq
C \left\| f \right\|_{\frac{m+1}{m}}$$
for all $f\in C_0^{\infty}(\Bbb R^2)$. The proof of this result is the same as that of $\delta=\frac{1}{m+1}$ and $n=1$. By scaling, $\delta=\frac{1}{m+1}$ is the only one case of interest in the theorem.

For $f\in C_0^{\infty}(\Bbb R^2)$, let $f_{\lambda}(t,x)=f(\lambda_1t,\lambda_2x)$ for $\lambda_i>0$. Then we have
\begin{equation*}
(R_{m,n}f_{\lambda})(t,x)
=
\frac{1}{\lambda_2}
R_{m,n}f\left(\lambda_1t, \frac{\lambda_1^{1/m}}{\lambda_2^{n/m}} x\right).
\end{equation*}
This implies
\begin{equation*}
|\partial_t|^{\delta}(R_{m,n}f_{\lambda}(t,x))
=
\frac{\lambda_1^{\delta}}{\lambda_2}
(|\partial_t|^{\delta}R_{m,n}f)\left(\lambda_1t, \frac{\lambda_1^{1/m}}{\lambda_2^{n/m}} x \right).
\end{equation*}
If there were a constant $C>0$ such that
\begin{equation*}
\left\|  |\partial_t|^{\delta}(R_{m,n}f_{\lambda})  \right\|_{L^p}
\leq
C \|f_{\lambda}\|_{L^p},
\end{equation*}
then we would obtain
\begin{equation*}
\frac{\lambda_1^{\delta}}{\lambda_2}
\lambda_1^{-\frac1p}
\frac{\lambda_2^{n/(mp)}  }{ \lambda_1^{1/(mp)} }
=
\lambda_1^{-\frac1p}\lambda_2^{-\frac1p}.
\end{equation*}
Hence we get $p=\frac{m+n}m$ and $\delta=\frac1{m+n}$.}

\label{Lemma-upper-Lp-bound}
For any $1\leq p \leq \infty$, it is true that
$$\|R_jf\|_{L^p}
\lesssim
\left( \frac{2^{mj}}{z}  \right)^N~2^{-mj}~2^{(m+1)j/p}$$
for all nonnegative integers $N$.

\label{Lemma-comparable-Lp-lemma}
There exists a small number $\epsilon_0\in (0,1)$ such that, for sufficiently large $j\gg  1$ and $z=\epsilon_0~2^{mj}$, it is true that
\begin{equation}\label{comparable-Lp-norm}
\|\partial_t^NR_jf\|_{L^p}
\approx
2^{-mj}~2^{(m+1)j/p},~~~N=0,1,2,3,4,
\end{equation}
where the implicit constants are independent of $j$.

We shall prove the above statement by a standard complex interpolation argument. Define a multiplier $T_{y}g(x)=\left(|2\pi \xi|^{iy}\widehat{g}(\xi)\right)^{\vee}(x)$ for $y\in\Bbb R$ and $g\in C_0^{\infty}(\Bbb R)$. The Marcinkiewicz multiplier theorem implies that
$\|T_yg\|_{L^p}\leq C(p)(1+|y|)\|g\|_{L^p}$ for all $1<p<\infty$; this is also true with $T_yg$ replaced by $T_{-y}g$. By the Plancherel theorem, one has $\|T_yg\|_{L^2}=\|g\|_{L^2}$. The simple observation $T_yT_{-y}g=g$ implies
\begin{equation}\label{multiplier-comparable-Lp}
C(p)^{-1}(1+|y|)^{-1}\|g\|_{L^p}
\leq
\|T_yg\|_{L^p}
\leq
C(p)(1+|y|)\|g\|_{L^p},~~~1<p<\infty,
\end{equation}
where $C(p)$ is independent of $y$.

For $h\in L^{p'}(\Bbb R^2)\cap C_0^{\infty}(\Bbb R^2)$, $\|h\|_{L^{p'}}\leq 1$, let
\begin{eqnarray*}
G(z)
&=&
\int_{\Bbb R^2}|\partial_t|^{z}R_jf(t,x)
\overline{h(t,x)}dtdx\\
&=&
\int_{\Bbb R^2}|2\pi\xi|^{z}\mathcal{F}_1R_jf(\xi,x)
\overline{\mathcal{F}_1h(\xi,x)}d\xi dx
\end{eqnarray*}
for $z$ in the strip $S:\beta\leq \,{\rm Re}\,(z) \leq 4$.
Then $G$ is analytic in the interior of $S$. It is also bounded and continuous on $S$. By (\ref{multiplier-comparable-Lp}), we have $|G(z)|\leq C(p)(1+|y|)\||\partial_t|^{\beta}R_jf\|_{L^p}$ for $\,{\rm Re}\,(z)=\beta$, and $|G(z)|\leq C(p)(1+|y|)\|\partial_t^{4}R_jf\|_{L^p}$ for $\,{\rm Re}\,(z)=4$.
Choose an $h$ such that $G(2)\geq \frac12\|\partial_t^{2}R_jf\|_{L^p}$. Hence, by complex interpolation, we have
\begin{equation*}
\|\partial_t^{2}R_jf\|_{L^p}
\lesssim
\||\partial_t|^{\beta}R_jf\|_{L^p}^{\theta}
\|\partial_t^{4}R_jf\|_{L^p}^{1-\theta},
~~~\beta\theta+4(1-\theta)=2.
\end{equation*}
By Lemma \ref{Lemma-comparable-Lp-lemma}, we obtain $$\||\partial_t|^{\beta}R_jf\|_{L^p}\gtrsim 2^{-mj}2^{(m+1)j/p}.$$
By a similar complex interpolation in the strip $0\leq \,{\rm Re}\,(z) \leq 2$, we also have
\begin{equation*}
\||\partial_t|^{\beta}R_jf\|_{L^p}\lesssim
\|R_jf\|_{L^p}^{1-\frac{\beta}2}
\||\partial_t|^{2}R_jf\|_{L^p}^{\frac{\beta}2}
\lesssim
2^{-mj}2^{(m+1)j/p}.
\end{equation*}
 The proof of the lemma is complete.

\label{Lemma-concentration-property}
There is a sufficiently small number $\epsilon_0>0$ such that for $j\gg 1$ and $z=\epsilon_0~2^{mj}$, it is true that
$$
\Big\|\partial_t^{l}Rf \Big\|_{L^{ \frac{m+1}{m}  }(\Bbb R^2)}
\approx 1,~~~l=1,2,3,4,$$
where the implicit bounds are independent of $j$. Moreover, for any small $\epsilon>0$, there is an $M\gg 1$ such that, for $l=1,2,3,4,$
\begin{equation}\label{Lemma-Lp-outside-annulus}
\Big\|\partial_t^{l}Rf \Big\|_{L^{\frac{m+1}{m}}\big(t\in\Bbb R,~|x|\leq 2^{j-M}\big)}
+
\Big\|\partial_t^{l}Rf \Big\|_{L^{\frac{m+1}{m}}\big(t\in\Bbb R,~|x|\geq 2^{j+M}\big)}
<\epsilon,
\end{equation}
where the choice of $M$ is independent of $j$.

\label{remark-complex-interpolation}
As in the proof of Lemma \ref{Lemma-comparable-Lp-lemma}, we can choose $\epsilon_0=2^{-m-1}$. The above lemma tells us that each function $\partial_t^{l}Rf $ is essentially supported on the rectangle $\{(t,x): |t|\leq 2^{mj},~|x|\approx 2^j\}$. Also by lemma \ref{Lemma-comparable-Lp-lemma} and its proof, one can verify that  $\| Rf \|_{L^{ \frac{m+1}{m} }}=+\infty$. However, we shall prove that $\| |\partial_t|^w Rf \|_{L^{ \frac{m+1}{m} }}<\infty$ for any complex number $w$ with $\,{\rm Re}\,(w)>0$. Write
\begin{equation*}
|\partial_t|^w Rf(t,x)
=
\int_{\Bbb R}\int_{\Bbb R}
e^{2\pi i t\xi}
e^{2\pi i \xi x^m y}
(2\pi|\xi|)^{w}\mathcal{F}_1\eta(\xi,y)e^{izy}dyd\xi,~~~\,{\rm Re}\,(w)>0.
\end{equation*}
Since $\eta$ is smooth with compact support, $\mathcal{F}_1\eta(\xi,y)$ is rapidly decreasing in $\xi$, and has compact support in $y$. Hence $|\partial_t|^w Rf$ is bounded. By the stationary phase method, the integral with respect to $y$ can be bounded by
\begin{equation*}
\left|
\int_{\Bbb R}
e^{2\pi i t\xi}
e^{2\pi i \xi x^my} (2\pi|\xi|)^{w}\mathcal{F}_1\eta(\xi,y)e^{izy}dy
\right|
\leq
C |\xi|^{\,{\rm Re}\,(w)}(1+|\xi x^m|)^{-N},~~~N>1+\,{\rm Re}\,(w),
\end{equation*}
where the constant $C$ depends on $z$ and $N$, but is independent of $\xi$ and $x$. This implies
\begin{equation*}
||\partial_t|^w Rf(t,x)|
\leq
C\int_{\Bbb R}
|\xi|^{\,{\rm Re}\,(w)}(1+|\xi x^m|)^{-N} d\xi
\leq
C|x|^{-m(1+\,{\rm Re}\,(w))}.
\end{equation*}
Note that $|\partial_t|^w Rf$ is bounded. Hence $\big||\partial_t\big|^w Rf(t,x)|\leq C\left(1+|x|^{m(1+\,{\rm Re}\,(w))} \right)^{-1}.$ Similarly, apply the stationary phase method to the integral with $\xi$. Then
 \begin{eqnarray*}
|\partial_t|^w Rf(t,x)
&=&
\int_{\Bbb R}\int_{\Bbb R}
\left(\frac{1}{2\pi i t}\right)
\frac{d}{d\xi}(e^{2\pi i t\xi})
e^{2\pi i \xi x^m y}
(2\pi|\xi|)^{w}\mathcal{F}_1\eta(\xi,y)e^{izy}dyd\xi\\
&=&
\left(-\frac{1}{2\pi i t}\right)
\int_{\Bbb R}\int_{\Bbb R}
e^{2\pi i t\xi}
\frac{\partial}{\partial\xi}
\Big(e^{2\pi i \xi x^m y}
(2\pi|\xi|)^{w}
\mathcal{F}_1\eta(\xi,y)\Big)
e^{izy}dyd\xi.
\end{eqnarray*}
Here if the partial derivative $\partial_{\xi}$ is taken with respect to $e^{2\pi i \xi x^m y}$, then the term $2\pi i x^my$ will appear, and one shall apply the stationary phase method to the integral in $y$ to obtain decay $(1+|x|^{m(1+\,{\rm Re}\,(w))} )^{-1}$. Hence we can obtain $\big||\partial_t\big|^w Rf(t,x)|\leq C(1+|t| )^{-1}.$

Combining the decay in $x$ and $t$, we get the desired estimate
\begin{equation*}
\big||\partial_t\big|^w Rf(t,x)|
\leq C
\left(1+|t|+|x|^{m(1+\,{\rm Re}\,(w))} \right)^{-1}.
\end{equation*}
This shows $|\partial_t\big|^w Rf\in L^{ \frac{m+1}{m} }(\Bbb R^2)$ provided that $\,{\rm Re}\,(w)>0$.

By complex interpolation, the inequality (\ref{lower-bound-for-Radon-transform}) is also true if the order $\frac1{m+1}$ is replaced by any positive $\delta>0$. In particular, for any $\delta\in (0,1)$,
\begin{equation*}\label{lower-bound-for-R(sum-fl)}
\left\|~\Big|  \partial_t \Big|^{  \delta  }  R\left( \sum\limits_{l=1}^Nf_l \right) ~ \right\|_{ L^{  \frac{m+1}{m}  }(\Bbb R^2)  }
\gtrsim  N^{  \frac{m}{m+1}  },
\end{equation*}
where the functions $f_l$ are defined as above. It should be pointed out that each $f_l$ is a smooth function supported in the rectangle $[-2,2]\times [1/2,4]$. Also, the above argument also applies to all $m>1$, not necessarily integers. For these reasons, we have
\begin{theorem}
\label{Thm-Failure-local-Radon-transform}
Assume $m>1$. Let $R_{m,1}f(t,x)$ be defined as in (\ref{Def-Rmn}) with $t\in\Bbb R$ and $x>0$.
Then for any $0<\delta<1$, there exists no constant $C>0$ such that
\begin{equation*}
\left\| ~\Big|  \partial_t \Big|^{  \delta  }  R_{m,1} f \right\|_{L^{\frac{m+1}{m}   }(\Bbb R\times \Bbb R^+)    }
\leq
C \|f\|_{L^{\frac{m+1}{m}   }(\Bbb R^2)}
\end{equation*}
for all $f\in C_0^{\infty}([-2,2]\times [1/2,4])$. Moreover, for general squares $[-\rho_0,\rho_0]\times [\rho_1,\rho_2]$ with $\rho_0>0$ and $\rho_2>\rho_1>0$, there is no constant $C$ such that the above estimate holds for all $f\in C_0^{\infty}([-\rho_0,\rho_0]\times [\rho_1,\rho_2])$.

\end{theorem}
The result of the above theorem is not scaling invariant. However, we only consider smooth functions $f$ supported in a fixed rectangle, for example $[-2,2]\times [1/2,4]$.
This theorem is also true for general $(m,n)$ with $m\neq n$ and for smooth functions $f$ supported in general squares $[-\rho_0,\rho_0]\times [\rho_1,\rho_2]$, where $\rho_0>0$ and $\rho_2>\rho_1>0$.

\label{Thm-Failure-local-Radon-transform}
Assume $m>1$. Let $R_{m,1}f(t,x)$ be defined as in (\ref{Def-Rmn}) with $t\in\Bbb R$ and $x>0$.
Then for any $0<\delta<1$, there exists no constant $C>0$ such that
\begin{equation*}
\left\| ~\Big|  \partial_t \Big|^{  \delta  }  R_{m,1} f \right\|_{L^{\frac{m+1}{m}   }(\Bbb R\times \Bbb R^+)    }
\leq
C \|f\|_{L^{\frac{m+1}{m}   }(\Bbb R^2)}
\end{equation*}
for all $f\in C_0^{\infty}([-2,2]\times [1/2,4])$. Moreover, for general squares $[-\rho_0,\rho_0]\times [\rho_1,\rho_2]$ with $\rho_0>0$ and $\rho_2>\rho_1>0$, there is no constant $C$ such that the above estimate holds for all $f\in C_0^{\infty}([-\rho_0,\rho_0]\times [\rho_1,\rho_2])$.

Without loss of generality, assume $S(x,0)=S(0,y)=0$. We need only to show the statement (i), and the statement (ii) follows by duality.

By a contradiction argument, assume $A_L>B_L$ and there is a constant $C$ such that
\begin{equation*}
\left\|
|\partial_t|^{\delta}Rf
\right\|_{L^p}
\leq
C\|f\|_{L^p}
\end{equation*}
is true for some $\delta$ and $p$ given as in (i). For $\lambda>0$, let $f_{\lambda}(t,x)=f(\lambda t,x)$. The variable $x$ is unchanged. For any $\mu>0$, define
\begin{equation*}
R_{\lambda,\mu}f(t,x)
=
\int_{-\infty}^{\infty}
f\left(t+\lambda S\left(\frac{x}{\mu},y\right)\right)
\varphi\left(
\frac{t}{\lambda},\frac{x}{\mu},y
\right)
dy.
\end{equation*}
By dilation, $\||\partial_t|^{\delta}(Rf_{\lambda})\|_{L^p}
=\lambda^{\delta}\lambda^{-\frac1p}\mu^{-\frac1p}
\||\partial_t|^{\delta}(R_{\lambda,\mu}f)\|_{L^p}$.
Also, $\|f_{\lambda}\|_{L^p}=\lambda^{-\frac1p}\|f\|_{L^p}$.
By our assumption, there is a constant $C$ such that $\left\|
|\partial_t|^{\delta}Rf_{\lambda}
\right\|_{L^p}
\leq
C\|f_{\lambda}\|_{L^p}$ for all $f\in C_0^{\infty}(\Bbb R^2)$. Let $\lambda=\mu^{A_L+1}$. Then
\begin{equation}\label{Bound-dilated-RT}
\left\|
|\partial_t|^{\delta}R_{\lambda,\mu}f
\right\|_{L^p}
\leq
C\|f\|_{L^p},~~~\delta=\frac{1}{A_L+1}\cdot\frac{1}{p},
\end{equation}
where $C$ is independent of $\lambda,\mu$ and $f$.

By Taylor's expansion,
\begin{eqnarray*}
\lambda S\left(\frac{x}{\mu},y\right)
&=&
\lambda \sum_{\alpha,\beta}
c_{\alpha,\beta}
\left(\frac{x}{\mu}\right)^{\alpha}y^{\beta}\\
&=&
\sum_{\alpha=A_L+1,\beta\geq B_L+1}
c_{\alpha,\beta}
x^{\alpha}y^{\beta}
+
\lambda\sum_{\alpha\geq A_L+2,\beta\geq 0}
c_{\alpha,\beta}
\left(\frac{x}{\mu}\right)^{\alpha}y^{\beta}\\
&=&
\sum_{\alpha=A_L+1,\beta\geq B_L+1}
c_{\alpha,\beta}
x^{\alpha}y^{\beta}
+
x^{A_L+1}
\sum_{\alpha\geq A_L+2,\beta\geq 0}
c_{\alpha,\beta}
\left(\frac{x}{\mu}\right)^{\alpha-A_L-1}y^{\beta}.
\end{eqnarray*}
For $\lambda=\mu^{A_L+1}$, taking $\mu\rightarrow \infty$, the limit of $\lambda S(x/\mu,y)$ is $$\widetilde{S}(x,y)=\sum\limits_{\alpha=A_L+1,\beta\geq B_L+1}
c_{\alpha,\beta}
x^{\alpha}y^{\beta}.$$
By Fatou's lemma, it follows from (\ref{Bound-dilated-RT}) that
\begin{equation}\label{limit-standard-RT-Section3}
\left\|
\big|\partial_t\big|^{\delta}
\int_{-\infty}^{\infty}
f(t+\widetilde{S}(x,y),y)\varphi(0,0,y)dy
\right\|_{L^p(\Bbb R^2)}
\leq
C\|f\|_{L^p(\Bbb R^2)}
\end{equation}
for all $f\in C_0^{\infty}(\Bbb R^2)$. Assume $S(x,y)$ is real analytic in the square $(-\rho,\rho)^2$ for some small number $\rho>0$. Without loss of generality, assume $c_{A_L+1,B_L+1}>0$. Take $\rho>0$ sufficiently small such that (i) $\varphi(0,0,y)\neq 0$ for $y\in(-\rho,\rho)$ and (ii) $\sum c_{\alpha,\beta}y^{\beta-B_L-1}
>\frac{c_{A_L+1,B_L+1}}{2}$ for $y\in(-\rho,\rho)$, where the summation is taken over $\alpha= A_L+1,\beta\geq B_L+1$. In (\ref{limit-standard-RT-Section3}), we take smooth $f$ supported in $(-1,1)\times (\rho_1,\rho_2)$ with $0<\rho_1<\rho_2<\rho$. By a change of variables,
\begin{equation*}
u
=h(y)=u(y)y,
\end{equation*}
where $u$ is given by
\begin{equation*}
u(y)=\left(
\sum_{\beta\geq B_L+1} c_{A_L+1,\beta}y^{\beta-B_L-1}
\right)^{\frac{1}{B_L+1}  },~~~y\in (-\rho,\rho).
\end{equation*}
Let $[\epsilon_1,\epsilon_2]=h([\rho_1,\rho_2])$ be the image of $h$ on $[\rho_1,\rho_2]$, and $h^{-1}$ the inverse of $h$. It follows from (\ref{limit-standard-RT-Section3}) that
\begin{equation*}\label{limit-standard-RT}
\left\|
\big|\partial_t\big|^{\delta}
\int_{-\infty}^{\infty}
f(t+x^{A_L+1}u^{B_L+1},h^{-1}(u))
\varphi(0,0,h^{-1}(u))\frac{dh^{-1}(u)}{du}du
\right\|_{L^p(\Bbb R^2)}
\leq
C\|f\|_{L^p(\Bbb R^2)}
\end{equation*}
for all $f\in C_0^{\infty}((-1,1)\times (\rho_1,\rho_2))$. Define a function $\widetilde{f}$ by
$$
\widetilde{f}(t,u)=
f(t,h^{-1}(u))
\varphi(0,0,h^{-1}(u))\frac{dh^{-1}(u)}{du}.
$$
Then $f\rightarrow \widetilde{f}$ is a one-to-one mapping from $C_0^{\infty}((-1,1)\times (\rho_1,\rho_2))$ onto $f\in C_0^{\infty}((-1,1)\times (\epsilon_1,\epsilon_2))$. Moreover, $f$ and $\widetilde{f}$ have comparable $L^p$ norms. As a consequence of the above inequality, we obtain
\begin{equation*}
\left\|
\big|\partial_t\big|^{\delta}
\int_{-\infty}^{\infty}
\widetilde{f}(t+x^{A_L+1}u^{B_L+1},u)du
\right\|_{L^p(\Bbb R^2)}
\leq
C\|\widetilde{f}\|_{L^p(\Bbb R^2)}
\end{equation*}
for all $\widetilde{f}\in C_0^{\infty}((-1,1)\times (\epsilon_1,\epsilon_2))$.
Let $[\tau_1,\tau_2]$ be the image of the mapping $u\rightarrow u^{B_L+1}$ for $u\in [\epsilon_1,\epsilon_2]$. For each $\widetilde{f}\in C_0^{\infty}((-1,1)\times (\epsilon_1,\epsilon_2))$, it is easy to verify that $g(t,y)=\widetilde{f}(t,y^{1/(B_L+1)})
y^{-B_L/(B_L+1)}$ is a smooth function in $C_0^{\infty}((-1,1)\times (\tau_1,\tau_2))$.
This correspondence is also one-to-one. Also, both $\widetilde{f}$ and $g$ have equivalent $L^p$ norms. Hence we get, for all $g\in C_0^{\infty}((-1,1)\times (\tau_1,\tau_2))$,
\begin{equation*}
\left\|
\big|\partial_t\big|^{\delta}
\int_{-\infty}^{\infty}
g(t+x^{A_L+1}y,y)dy
\right\|_{L^p(\Bbb R^2)}
\leq
C\|g\|_{L^p(\Bbb R^2)},
\end{equation*}
where $\frac{A_L+B_L+2}{A_L+1}\leq p<2$ and $\delta=\frac{1}{(A_L+1)p}$. Now we embed the left hand side in an analytic family of operators
\begin{equation*}
V_zg(t,x)=
x_{+}^{az}
\int_{\Bbb R}|\partial_t|^{L(z)}
g(t+x^{A_L+1}y,y)dy,~~~0\leq \,{\rm Re}\,(z) \leq 1,
\end{equation*}
where $a>0$ is to be determined and $L(z)=\frac{1-z}{A_L+B_L+2}+\frac{z}{2N_2}$. Here $N_2>1$ is a number to be fixed. We shall also find a number $N_1>$ such that $\frac{N_1}{N_1+1}
=\frac{\theta}{p}+\frac{1-\theta}{2}$ for some $\theta\in (0,1)$. The first step is to choose a $\theta\in (0,1)$ such that it is sufficiently close to $1$. Then $N_1$ is uniquely determined and sufficiently close to $\frac{1}{p-1}$. The second step is to determine $a>0$ such that $$\frac{A_L+1}{1+a\theta\frac{N_1+1}{N_1}}=N_1,
~~~
N_2=\frac{A_L+1}{1+2a}> 1.$$
The first equation gives
$$a=\frac{1}{\theta}
\left(\frac{A_L+1}{N_1+1}
-
\frac{N_1}{N_1+1}\right).$$
Since $N_1$ is close to $\frac{1}{p-1}>1$, it is true that $a<\frac{A_L}{2}$. Hence $N_2=\frac{A_L+1}{1+2a}>1$ for $\theta$ near one. By complex interpolation, for $z=\theta$, we get
\begin{equation*}
\left\|
\big|\partial_t\big|^{L(\theta)}
\int_{-\infty}^{\infty}
g(t+x^{N_1}y,y)dy
\right\|_{L^{\frac{N_1+1}{N_1}}(\Bbb R\times\Bbb R^+)}
\leq
C\|g\|_{\frac{N_1+1}{N_1}}
\end{equation*}
for all $g\in C_0^{\infty}((-1,1)\times (\tau_1,\tau_2))$. This is impossible by Theorem \ref{Thm-Failure-local-Radon-transform}. The proof of the theorem is complete.

\label{Thm-L2-Damped-RT-Hessian}
Let $R_{dam}$ be defined as above. Then there exists a constant $C$ such that
\begin{equation*}
\|R_{dam}f\|_{L^2_{1/2}}
\leq C(1+|\,{\rm Im}\,(z)|^2)\|f\|_{L^2},~~~\,{\rm Re}\,(z)=\frac12.
\end{equation*}

\label{lemma-frac-integral-oper}
Assume $a>0$, $b\leq\frac{1}{2}$, and $T$ is an integral operator defined by
\begin{equation*}
Tf(x)=\int_{0}^{1}\left|x-y^a\right|^{-b}f(y)dy.
\end{equation*}
Then $T$ is bounded from $L^2(0,1)$ into itself. Moreover, if $r(y)=\sum_{n=1}^{\infty}a_ny^{n\delta}$ is an absolutely convergent Puiseux series near the orgin, $\delta>0$ a rational number, and $a_1\neq 0$, then the operator
\begin{equation*}
\widetilde{T}f(x)
=
\int_{0}^{\epsilon_0}\left|x-r(y)\right|^{-b}f(y)dy.
\end{equation*}
is bounded on $L^2(0,\epsilon_0)$, where $\epsilon_0>0$ is a small number.

\label{lemma-Charac-Finite-Diff}
For $s\in(0,1)$, there exist two constants $C_1,C_2>0$ such that, for all $f\in L^2_s(\Bbb R)$,
\begin{equation*}
C_1\|f\|_{L^2_s}
\leq
\|f\|_{L^2}+
\left(
\int_{\Bbb R}\int_{\Bbb R}
\frac{|f(x+h)-f(x)|^2}{|h|^{1+2s}}
dxdh
\right)^{\frac12}
\leq
C_2\|f\|_{L^2_s}.
\end{equation*}

It is more convenient to replace the smooth cut-off function $\varphi(t,x,y)\in C_0^{\infty}(\Bbb R^3)$ by $\varphi(x,y)\in C_0^{\infty}(\Bbb R^2)$. In fact, for every $\varphi(t,x,y)\in C_0^{\infty}(\Bbb R^3)$, we use the Fourier expansion to write $\varphi(t,x,y)=
\sum_{k\in\mathbb{Z}}\eta_k(t)\varphi_k(x,y)$,
where $\eta\in C_0^{\infty}(\mathbb{R})$ and
$\varphi_k\in C_0^{\infty}(\mathbb{R}^2)$ have uniformly bounded compact supports. Moreover, for each positive integer $N$, $\|\eta_k\|_{C^N}$ is of $O(|k|^N)$ and $\|\varphi_k\|_{C^N}$ are rapidly decreasing in $k$. If $R_{dam}$ is bounded from $L^2$ into $L^{2}_{1/2}$ for every cut-off $\varphi(x,y)$, then we can use Lemma \ref{Kato-Ponce-ineq} to obtain the desired result in the theorem.

Obviously, $R_{dam}$ is bounded from $L^2(\Bbb R^2)$ into itself. Take partial Fourier transform of $R_{dam}f(t,x)$ with respect to $t$, denoted by $\widehat{R_{dam}f}(\xi,x)$. Then
\begin{equation*}
\widehat{R_{dam}f}(\xi,x)
=
\int_{\Bbb R}e^{2\pi i\xi S(x,y)}
|S_{xy}''(x,y)|^z\widehat{f}(\xi,y)\varphi(x,y)dy.
\end{equation*}
By the theorem of Phong and Stein in \cite{PS1997},
\begin{equation*}
\|\widehat{R_{dam}f}(\xi,\cdot)\|_{L^2(\Bbb R)}
\leq C|\xi|^{-\frac12}
\|\widehat{R_{dam}f}(\xi,\cdot)\|_{L^2(\Bbb R)},
\end{equation*}
where $C$ is independent of $\xi$. By Plancherel's theorem, $|\partial_t|^{\frac12}R_{dam}$ is bounded on $L^2$.

Now we have to show that $|\partial_x|^{\frac12}R_{dam}$ is bounded on $L^2$. The above Fourier transform method does not work in this situation. The finite difference characterization of $L^2_s$ will be used; see Lemma \ref{lemma-Charac-Finite-Diff}. More precisely, it suffices to show that
\begin{equation*}
\int_{\Bbb R}\int_{\Bbb R}\int_{\Bbb R}
\frac{|\widehat{R_{dam}f}(\xi,x+h)- \widehat{R_{dam}f}(\xi,x)|^2}{|h|^2}
dxdhd\xi
\lesssim
\|f\|_{L^2}^2.
\end{equation*}
In view of the fact that $R_{dam}$ is bounded on $L^2$, we can restrict the integral in $h$ to $|h|\leq 1$. On the other hand, the theorem of Phong and Stein implies $\|\widehat{R_{dam}f}(\xi,\cdot)\|_{L^2(\Bbb R)}
\lesssim |\xi|^{-\frac12}
\|\widehat{f}(\xi,\cdot)\|_{L^2(\Bbb R)}$.
Hence
\begin{eqnarray*}
&&
\int_{\Bbb R}
\left(\int_{\Bbb R}\int_{|h|>|\xi|^{-1}}
\frac{|\widehat{R_{dam}f}(\xi,x+h)- \widehat{R_{dam}f}(\xi,x)|^2}{|h|^2}
dxdh\right)
d\xi\\
&\lesssim &
\int_{\Bbb R}
\left(|\xi|^{-1}\|\widehat{f}(\xi,\cdot)\|_{L^2(\Bbb R)}^2
\int_{|h|>|\xi|^{-1}}
\frac{1}{|h|^2}
dh\right)
d\xi \lesssim
\|f\|_{L^2}^2.
\end{eqnarray*}
With this observation, it suffices to consider the integral in the domain $|h\xi|\leq 1$.

By the chain rule, write
\begin{eqnarray}\label{Equ-Wh1-Wh2}
& &
\widehat{R_{dam}f}(\xi,x+h)
-
\widehat{R_{dam}f}(\xi,x) \nonumber \\
&=&
\int_{\Bbb R}
\left(e^{2\pi i \xi S(x+h,y)}-e^{2\pi i \xi S(x,y)}\right)
|S''_{xy}(x+h,y)|^z\widehat{f}(\xi,y)
\varphi(x+h,y)dy  \nonumber \\
& &
+
\int_{\Bbb R}e^{2\pi i \xi S(x,y)}
\left(
|S''_{xy}(x+h,y)|^z \varphi(x+h,y)
-
|S''_{xy}(x,y)|^z \varphi(x,y)
\right)
\widehat{f}(\xi,y)dy   \nonumber  \\
&=&
W^{(1)}_{h}\widehat{f}(\xi,x)
+W^{(2)}_{h}\widehat{f}(\xi,x).
\end{eqnarray}
Write
\begin{eqnarray*}
&&
W^{(1)}_{h}\widehat{f}(\xi,x)\\
&=&
\int_{\Bbb R}
\left(1-e^{2\pi i \xi (S(x,y)-S(x+h,y))}\right)
e^{2\pi i \xi S(x+h,y)}
|S''_{xy}(x+h,y)|^z\widehat{f}(\xi,y)
\varphi(x+h,y)dy.\\
\end{eqnarray*}
If $|h\xi|\leq 1$ and $|h|\leq 1$, the factor $1-e^{2\pi i \xi (S(x,y)-S(x+h,y))}$ can be inserted into the cut-off function, and its $C^2$ norm is not greater than $C|h\xi|$. We use again the theorem of Phong and Stein to obtain
\begin{equation*}
\|W^{(1)}_{h}\widehat{f}(\xi,\cdot)\|_{L^2(\Bbb R)}
\lesssim
|h\xi| |\xi|^{-\frac12}
\|\widehat{f}(\xi,\cdot)\|_{L^2(\Bbb R)}.
\end{equation*}
It follows that
\begin{eqnarray*}
\int_{\Bbb R}
\left(\int_{|h|<\,{\rm min}\{1,|\xi|^{-1}\} }
\int_{\Bbb R}
\frac{|W^{(1)}_{h}\widehat{f}(\xi,x)|^2}{|h|^2}
dxdh\right)
d\xi
&\lesssim&
\int_{\Bbb R}
\left( |\xi|
\|\widehat{f}(\xi,\cdot)\|_{L^2(\Bbb R)}^2
\int_{|h|<|\xi|^{-1} }
dh\right)
d\xi\\
&\lesssim&
\|f\|_{L^2}^2.
\end{eqnarray*}
In contrast to $W_h^{(1)}$, the oscillation effect will not be used for our estimates of $W_h^{(2)}$. Write
\begin{eqnarray*}
&&
|S''_{xy}(x+h,y)|^z \varphi(x+h,y)
-
|S''_{xy}(x,y)|^z \varphi(x,y)\\
&=&
(|S''_{xy}(x+h,y)|^z
-
|S''_{xy}(x,y)|^z )
\varphi(x+h,y)
+
|S''_{xy}(x,y)|^z
( \varphi(x+h,y)-\varphi(x,y))\\
&=&
(|S''_{xy}(x+h,y)|^z
-
|S''_{xy}(x,y)|^z )
\varphi(x+h,y)+O(h).
\end{eqnarray*}
For our purpose, we require an elementary inequality. Assume $0<a,b\leq 1$ and $\,{\rm Re}\,(w)>0$. Then for any $\theta\in [0,1]$, there exists a constant $C$ such that
\begin{equation*}
|a^{w}-b^w|
\leq
C|a-b|^{\theta}
\left(a^{\,{\rm Re}\,(w)\theta-\theta}
+b^{\,{\rm Re}\,(w)\theta-\theta} \right).
\end{equation*}
Now we give a proof. By a simple interpolation, it is enough to consider $\theta=1$. If $a\geq 2b$ or $b\geq 2a$, then $|a^{w}-b^w|\leq a^{\,{\rm Re}\,(w)}+b^{\,{\rm Re}\,(w)}$. Both $a^{\,{\rm Re}\,(w)}$ and $b^{\,{\rm Re}\,(w)}$ are bounded by the right hand side of the above inequality. If $\frac{b}2<a<2b$, then
\begin{equation*}
a^{w}-b^w
=
(a-b)w\int_0^1
\Big(a\tau+b(1-\tau)\Big)^{w-1}d\tau.
\end{equation*}
Taking the absolute value of both sides, we obtain the desired inequality.

By the Puiseux Theorem, write $S_{xy}''$ as
\begin{equation*}
S_{xy}''(x,y)=V(x,y)x^my^s\prod_{i=1}^M(x-r_i(y)),
\end{equation*}
where $V(x,y)\neq 0$ near the origin.
By the chain rule, for $\,{\rm Re}\,(z)=\frac12$,
\begin{eqnarray}\label{Chain-rule-Damping-Factor}
&&
\Big|\Big(|S''_{xy}(x+h,y)|^z
-
|S''_{xy}(x,y)|^z \Big)
\varphi(x+h,y)\Big|\nonumber\\
&=&
\left|\Big|V(x+h,y)(x+h)^my^s
\prod_{i=1}^M(x+h-r_i(y))\Big|^z
-\Big|V(x,y)x^my^s\prod_{i=1}^M(x-r_i(y))\Big|^z \right|
|\varphi(x+h,y)|\nonumber\\
&\lesssim &
m|x+h|^{\frac{m\theta}{2}-\theta}|h|^{\theta}
+m|x|^{\frac{m\theta}{2}-\theta}|h|^{\theta}
+
\sum\limits_{i=1}^{M}
\Big(
|x+h-r_i(y)|^{-\theta_i/2}|h|^{\theta_i}
+
|x-r_i(y)|^{-\theta_i/2}|h|^{\theta_i}
\Big)\nonumber\\
&&
+O(h),
\end{eqnarray}
where $\theta,\theta_i\in [0,1]$ can be chosen arbitrarily. By the definition of $W_h^{(2)}$ in (\ref{Equ-Wh1-Wh2}), assuming $|h|\leq 1$, we obtain
\begin{eqnarray}\label{inequality-decomp-Wh2}
&&
|W_h^{(2)}f(x)|\nonumber\\
&\lesssim&
m|x+h|^{\frac{m\theta}2 - \theta}|h|^{\theta}\|\widehat{f}(\xi,\cdot)\|_{L^2}
+
m|x|^{\frac{m\theta}2 - \theta}|h|^{\theta}\|\widehat{f}(\xi,\cdot)\|_{L^2}
\nonumber\nonumber\\
&&
+
\sum_{i=1}^M|h|^{\theta_i}
\int_{|y|\lesssim 1}\left(
|x+h-r_i(y)|^{-\theta_i/2}
+
|x-r_i(y)|^{-\theta_i/2}
\right)|\widehat{f}(\xi,y)|dy.
\end{eqnarray}
If $m\geq 1$, let $\theta=\frac{1}{2}$. Choose $\theta_i=1$ for $i=1,2,\cdots,M$. If $m\geq 1$, a direct calculation gives
\begin{equation*}
\int_{|x|\lesssim 1}\int_{|h|\leq 1}\int_{\xi\in\Bbb R}
\frac{|x+h|^{\frac{m}2-1}
|h|^2\|f(\xi,\cdot)\|_{L^2}^2}{h^{2}}
dxdhd\xi
\lesssim
\|f\|_{L^2(\Bbb R^2)}^2.
\end{equation*}
This inequality is also true if $|x+h|^{\frac{m}2-1}$ is replaced by $|x|^{\frac{m}2-1}$. Note that all $r_i$ are absolutely convergent Puiseux series near the origin. By Lemma \ref{lemma-frac-integral-oper}, the $L^2$ norm, with respect to $x$, of the summation in (\ref{inequality-decomp-Wh2}) is bounded by $C|h|\|\widehat{f}(\xi,\cdot)\|_{L^2(\Bbb R)}$.
Combining these two estimates, we get
\begin{equation*}
\int_{|x|\lesssim 1}\int_{|h|\leq 1}\int_{\xi\in\Bbb R}
\frac{|W_h^{(2)}\widehat{f}(\xi,x)|^2}{h^{2}}
dxdhd\xi
\lesssim
\|f\|_{L^2(\Bbb R^2)}^2.
\end{equation*}
Our proof of the theorem is complete.

Let $R_{dam}$ be defined as (\ref{damped-RT}) with $D$ in place of $S''_{x,y}$, i.e.,
\begin{equation*}
R_{dam}f(t,x)=
\int_{-\infty}^{\infty}f(t+S(x,y),y)
|D(x,y)|^z
\varphi(t,x,y)dy.
\end{equation*}
Assume $(A_0,B_0)$ is the leftmost extreme point of the Newton polyhedron of $S''_{xy}$, and $A_0\leq B_0$. Then there exists a constant $C$ such that
\begin{equation}
\|R_{dam}f\|_{L^2_{1/(1+A_0)}}
\leq
C(1+|\,{\rm Im}\,(z)|^2)\|f\|_{L^2},
~~~\,{\rm Re}\,(z)=\frac{B_0-A_0}{2B_0}\cdot \frac{1}{1+A_0}.
\end{equation}

Our argument is very similar to the proof of Theorem
\ref{Thm-L2-Damped-RT-Hessian}. For regularity with respect to $t$, we take the partial Fourier transform relative to $t$. Then
\begin{equation*}
\widehat{R_{dam}f}(\xi,x)=
\int_{-\infty}^{\infty}e^{2\pi i \xi S(x,y)}\widehat{f}(\xi,y)
|D(x,y)|^z
\varphi(x,y)dy.
\end{equation*}
By the damping estimate in \cite{ShiXuYan}, then
\begin{equation*}
\|\widehat{R_{dam}f}(\xi,\cdot)\|_{L^2(\Bbb R)}
\leq
C|\xi|^{-\frac{1}{2(1+A_0)}}
\|\widehat{f}(\xi,\cdot)\|_{L^2(\Bbb R)}.
\end{equation*}
The constant $C$ is independent of $\xi$. Hence
\begin{equation*}
\int_{\Bbb R}|\xi|^{\frac{1}{1+A_0}}
\|\widehat{R_{dam}f}(\xi,\cdot)\|_{L^2(\Bbb R)}^2
d\xi
\lesssim
\|f\|_{L^2(\Bbb R^2)}.
\end{equation*}
This implies that the required regularity for $t$ is true, since $R_{dam}$ is bounded on $L^2(\Bbb R^2)$.

Now we turn to the regularity in the variable $x$. By Lemma \ref{lemma-Charac-Finite-Diff} and similar reasons as in our proof of Theorem \ref{Thm-L2-Damped-RT-Hessian}, it is suffices to prove
\begin{equation*}
\int_{\Bbb R}
\left(
\int_{|h|<\,{\rm min}\{1,|\xi|^{-1}\}}\int_{\Bbb R}
\frac{|\widehat{R_{dam}f}(\xi,x+h)- \widehat{R_{dam}f}(\xi,x)|^2}{|h|^{ 1+\frac{1}{1+A_0} } }
dxdh
\right)
d\xi
\lesssim
\|f\|_{L^2}^2.
\end{equation*}
The remaining argument follows the proof of Theorem \ref{Thm-L2-Damped-RT-Hessian} step by step. A slight difference lies in the chain rule for damping factor. For our purpose, we shall replace (\ref{Chain-rule-Damping-Factor}) by
\begin{eqnarray*}
&&
\Big|\Big(|D(x+h,y)|^z
-
|D(x,y)|^z \Big)
\varphi(x+h,y)\Big|\nonumber\\
&=&
\left|\Big|V(x+h,y)y^s
\prod_{i=1}^M(x+h-r_i(y))\Big|^z
-\Big|V(x,y)y^s\prod_{i=1}^M(x-r_i(y))\Big|^z \right|
|\varphi(x+h,y)|\nonumber\\
&\lesssim &
\sum\limits_{i=1}^{M}
\Big(
|x+h-r_i(y)|^{-(1-\,{\rm Re}\,(z))\theta_i}|h|^{\theta_i}
+
|x-r_i(y)|^{-(1-\,{\rm Re}\,(z))\theta_i}|h|^{\theta_i}
\Big)
+O(h),
\end{eqnarray*}
where $\,{\rm Re}\,(z)=\frac{B_0-A_0}{2B_0}\cdot\frac{1}{1+A_0}\geq0$, and $\theta_i\in [0,1]$ are to be determined. If $A_0=0$, then $\,{\rm Re}\,(z)=\frac12$ and let $\theta_i=1$. If $A_0>0$, choose $\frac12\leq \theta_i<1$ such that $(1-\,{\rm Re}\,(z))\theta_i\leq \frac12$. This is possible since $0<1-\,{\rm Re}\,(z)\leq 1$. Specially, one can take $\theta_i=\frac12$ for $A_0>0$.

\label{Thm-perturbation-HT}
Assume $S$ is real-analytic and almost translation invariant near the origin in $\mathbb{R}^2$, and its Hessian $S_{xy}''$ is of the form $S_{xy}''(x,y)=
U(x,y)\prod_{i=1}^{N}(x-r_{i}(y))$. Define
\begin{equation*}
T_zf(x)=\left(  z+\frac{1}{N}  \right)
\int_{-\epsilon_0}^{\epsilon_0}
\prod_{i=1}^{N}|x-r_i(y)|^zf(y)dy,~~~\,{\rm Re}\,(z)=-\frac{1}{N},
\end{equation*}
where $\epsilon_0>0$ is a sufficiently small number, and $f\in C_0^{\infty}(-\epsilon_0,\epsilon_0)$. Let $\alpha_1(y)=\sum_{k=1}^{\infty}c_kx^{k/n_1}$ be the real part of $r_1(y)$ with $n_1$ a positive integer, and $\sigma_1(y)=\sum_{j=1}^{\infty}c_{jn_1}x^j$ the analytic part of $\alpha_1$. Define a singular integral operator $H_z$ by
\begin{equation}
H_zf(x)=\left(  z+\frac{1}{N}  \right)
\int_{\mathbb{R}}
|x-\sigma_1(y)|^{Nz}f(y)dy,~~~\,{\rm Re}\,(z)=-\frac{1}{N}.
\end{equation}
Let $H^{\ast}_{z}$ be the maximal operator of $H_z$, defined by
\begin{equation*}
H_z^{\ast}f(x)=\sup_{\epsilon>0}\left|\left(  z+\frac{1}{N}  \right)
\int_{|x-\sigma_1(y)|>\epsilon}
|x-\sigma_1(y)|^{Nz}f(y)dy \right|.
\end{equation*}
Then there exists a nonnegative kernel $K(x,y)$ in $(-\epsilon_0,\epsilon_0)^2$ such that the integral operator associated with $K$ is bounded on $L^p$ for $1\leq p\leq \infty$, and
\begin{equation}\label{truncated-maximal-sing-oper}
|T_zf(x)|
\lesssim
H_z^{\ast}(f)(x)+\int_{-\epsilon_0}^{\epsilon_0}
K(x,y)|f(y)|dy
\end{equation}
for all $x\in (-\epsilon_0,\epsilon_0)$ and $f\in C_0^{\infty}(-\epsilon_0,\epsilon_0)$.

For clarity, we shall divide our proof into two cases.
\vspace{0.5\baselineskip}

{\bf Case 1. $r_1(y)=\sigma_1(y)$}
\vspace{0.5\baselineskip}

If all $r_i(x)=r_1(x)$, then $T_z=H_z$ and our proof is done. Suppose $r_i(x)\neq r_1(x)$ for some $i$. Assume $r_1,r_2,\cdots,r_N$ have $m$ distinct functions, denoted by $r_1,r_2,\cdots,r_m$. Then
\begin{equation*}
\prod_{i=1}^{N}\left(x-r_i(y)\right)
=
\prod_{i=1}^{M}\left(x-r_i(y)\right)^{m_i},
\end{equation*}
where $m_i$ is the multiplicity of $r_i$. For $i=2,\cdots,M$, we can write $r_i$ as $r_i(y)-\sigma_1(y)=C_iy^{d_i}+o(y^{d_i})$ as $y\rightarrow 0$, where the constant $C_i\neq 0$ and $d_i\leq d_j$ if $i\leq j$. If $d_i=d_j$ for some $2\leq i <j \leq M$, we also assume $|C_i|\geq |C_j|$.
\vspace{0.5\baselineskip}

Decompose $T_z$ as $T_z=\sum_{i=0}^{4}W_i$, where $W_i$ are defined by
\begin{equation*}
W_kf(x)
=\left(z+\frac1N  \right)
\int_{A_k}
\prod_{i=1}^{N}|x-r_i(y)|^z
f(y)dy,
\end{equation*}
where $z$ has real part $\,{\rm Re}\,(z)=-\frac{1}{N}$, and $A_k$ are defined by
\begin{eqnarray*}\label{CZ-part-Tz}
A_0
&=&
\{(x,y):|x-\sigma_1(y)|> 100|x|\},\\
A_1
&=&
\left\{(x,y):\frac{|x|}{100}\leq |x-\sigma_1(y)| \leq 100|x|\right\},\\
A_2
&=&
\left\{(x,y):100 |C_2y^{d_2}|\leq |x-\sigma_1(y)| <\frac{|x|}{100}\right\},\\
A_3
&=&
\left\{(x,y):\frac{|C_2y^{d_2}|}{100} \leq |x-\sigma_1(y)| <100|C_2y^{d_2}|\right\},\\
A_4
&=&
\left\{(x,y):|x-\sigma_1(y)|<
\frac{|C_2y^{d_2}|}{100}\right\}.
\end{eqnarray*}
To estimate $W_k$, we define
\begin{equation}\label{Def-Vi-truncated-sin-int}
V_kf(x)
=
\left(  z+\frac{1}{N}  \right)
\int_{A_k}
|x-\sigma_1(y)|^{Nz}
f(y)dy.
\end{equation}
For small $x,y$, $|x-r_1(y)|> 100|x|$ implies $|x-r_1(y)|\geq 100 |C_1 y^{d_2}|$. To see this, by the assumptions $r_1(0)=0$ and $r_1'(0)=1$, we see that $|x-r_1(y)|\approx |y|$ if $|x-r_1(y)|> 100|x|$. For small $x,y$, our claim is verified since $d_2>1$. Then
\begin{equation*}
|W_0f(x)
-
V_0f(x)|
\lesssim
\int_{A_0}
|x-r_1(y)|^{-2}
|y^{d_2}||f(y)|dy.
\end{equation*}
If we replace $A_0$ by $|x-r_1(y)|\geq 100 |C_1 y^{d_2}|$, then $W_0-V_0$ is bounded on $L^1$. On the other hand, $|y|\gtrsim |x|$ for $(x,y)\in A_0$. Observe that the kernel of $W_0-V_0$ is bounded by $C|y|^{d_2-2}$ since $|x-r_1(y)|\approx |y|$. Hence $W_0-V_0$ is also bounded on $L^{\infty}$.
\vspace{0.5\baselineskip}

For $W_1$, we use the same argument as above. Similarly,
\begin{equation*}
|W_1f(x)
-
V_1f(x)|
\lesssim
\int_{A_1}
|x-r_1(y)|^{-2}
|y^{d_2}||f(y)|dy.
\end{equation*}
For $(x,y)\in A_1$, it is clear that $|y|\lesssim |x|$. Then $|x-r_1(y)|^{-2}|y^{d_2}|\lesssim |x|^{-2}|y|^{d_2}$. Since $d_2>1$,
$W_1-V_1$ is bounded on $L^{\infty}$. Similarly, we also have $|x-r_1(y)|\gtrsim |y|^{d_2}$ in $A_1$. This implies that $W_1-V_1$ is bounded on $L^1$.
\vspace{0.5\baselineskip}

In view of
\begin{equation*}
|W_2f(x)
-
V_2f(x)|
\lesssim
\int_{A_2  }
|x-r_1(y)|^{-2}
|y^{d_2}||f(y)|dy.
\end{equation*}
It follows immediately that $W_2-V_2$ is bounded on $L^1$. For points in $A_2$, we deduce $|y|\approx |x|$. Then $|y|^{d_2}\approx |x|^{d_2}$ and $|x-r_1(y)|\gtrsim |x|^{d_2}$. Hence $W_2-V_2$ is also bounded on $L^{\infty}$.
\vspace{0.5\baselineskip}

The arguments for estimate of $W_3,W_4$ are somewhat different and more direct. First observe that $|x|\approx |y|$ for points in either $A_3$ or $A_4$. The distance between the singularities $r_i(y)$ is of order $O(|y|^{d_2})$. Each integral is taken over a measurable set of measure $O(|y|^{d_2})$. Hence both $W_3$ and $W_4$ are bounded on $L^{1}$. For example, we see that the kernel of $W_3$ has absolute value bounded by $C|y|^{-m_1d_2/N}
\prod_{i=2}^{M}|x-r_i(y)|^{-m_i/N}$.
A rearrangement inequality yields
$$\int_{A_3}\prod_{i=2}^{M}|x-r_i(y)|^{-\frac{m_i}N}
dx
\leq
\int_{|x|\lesssim |y|^{d_2}}|x|^{-1+\frac{m_1}{N}}
dx
\lesssim
|y|^{m_1d_2/N}.$$
Hence $W_3$ is bounded on $L^{1}$. By the symmetry of $x$ and $y$, it is also bounded on $L^{\infty}$. A similar argument yields that $W_4$ is bounded on $L^p$ for $1\leq p \leq \infty$.
\vspace{0.5\baselineskip}

{\bf Case 2. $r_{1}(y)\neq \sigma_1(y)$}
\vspace{0.5\baselineskip}

As in Case 1, suppose
$\prod_{i=1}^{N}\left(x-r_i(y)\right)=
\prod_{i=1}^{M}\left(x-r_i(y)\right)^{m_i},$
where $m_i$ is the multiplicity of $r_i$.
For $i=1,\cdots,M$, assume $r_i(y)-\sigma_1(y)=C_iy^{d_i}+o(y^{d_i})$ with $C_i\neq 0$ and $d_i>1$ for $i=1,\cdots,M$. Also assume $d_2\leq d_3\leq \cdots \leq d_M$. Also, if $d_i=d_j$ for some $2\leq i <j \leq M$, we also assume $|C_i|\geq |C_j|$. Here we do not know whether $d_1$ is large than $d_2$.

The simplest case is $d_1>d_2$. Then $r_2(y)-r_1(y)=C_2y^{d_2}+o(y^{d_2})$ as $y\rightarrow 0$. The argument in Case 1 is also applicable.

Consider the case $d_1=d_2$. The proof method in Case 1 can be adapted to this case. In the definition of $A_k$, the constant $C_2$ shall be replaced by $\,{\rm max}\{|C_1|,|C_2|\}$. If $d_1$ is not an integer, then $d_1=\frac{v}{u}$ and $u,v>0$ are relatively prime integers.  Since $S$ is real analytic, $\prod_{i=1}^{M}(x-r_i(y))^{m_i}$ is conjugate invariant. This implies that $r_i(y)=\sigma_1(y)+\exp({\frac{2\pi v }{u}}\sqrt{-1})C_1y^{d_1}+o(y^{d_1})$ for some $i\geq 2$. Hence there exists some $i\geq 2$ such that $r_i(y)-r_1(y)=Cy^{d_2}+o(y^{d_2})$
with $C\neq 0$. If $d_1$ is an integer, then $C_1$ is a pure imaginary number. Hence
$|x-r_1(y)|\gtrsim |y|^{d_2}$. All estimates in Case 1 are also true.

The final case is $d_1<d_2$. In view of $d_1>1$,
we use the conjugate invariance to obtain that $d_1$ is an integer and $C_1$ is a pure imaginary number. If $d_1$ were not an integer, then $r_1$ would have at least one conjugate Puiseux $r_j$. Then $r_j(y)-\sigma_1(y)=Cy^{d_1}+o(y^{d_1})$ for some $C\neq 0$. This contradicts our previous assumptions. Hence $d_1>1$ is an integer. By our definition of $\sigma_1(y)$, it is the analytic part of the real part of $r_1(y)$. This implies that $C_1$ is an imaginary number. Now we turn to estimates of $W_k$. The above argument in Case 1 should be modified slightly. Let $A_k$ be defined as Case 1 with $C_1y^{d_1}$ in place of $C_2y^{d_2}$. Our estimates for $W_0,W_1,W_2$ are the same as above. For $W_3,W_4$, first observe $|x-r_1(y)|\gtrsim |y|^{d_1}$ since $C_1y^{d_1}$ is contained in the imaginary part of $r_1(y)$. The argument in Case 1 also holds here.
\vspace{0.5\baselineskip}

Finally, each $V_k$ satisfies the estimate (\ref{truncated-maximal-sing-oper}). Combining this fact with the above results, our proof is complete.

\label{Thm-Maximal-RT}
Assume the maximal operator $T^\ast$ is defined by {\rm (\ref{maximal truncated operator})}. Then for every $1<p<\infty$, there exists a constant $C_p>0$ such that
$$\| T^{\ast}f\Vert_{L^p(\Bbb R^n)}\leq C_p \| f\Vert_{L^p(\Bbb R^n)},~~~1<p<\infty.$$

\label{S6lemma1}
Assume $S$ is a real-valued real-analytic function near the origin in the plane, and satisfies the assumptions in (\ref{Sxy}). Then the mapping $$\gamma_t(x)=\left(x_1-t,x_2-S(x_1,x_1-t)\right)$$
 does not have an invariant submanifold at $(0,0)\in \mathbb{R}^2\times\mathbb{R}$, with positive codimension.

For small $t_1$ and $t_2$, let $\Gamma(x,t_1,t_2)$ be the composition $\gamma_{t_2}\circ\gamma_{t_1}(x)$. Then
\begin{equation*}
\Gamma(x,t_1,t_2)
=
\Big(
x_1-t_1-t_2,~
x_2-S(x_1,x_1-t_1)-S(x_1-t_1,x_1-t_1-t_2)
\Big).
\end{equation*}
Hence
\begin{eqnarray*}
\frac{\partial \Gamma}{\partial t_1}
&=&
\Big(-1,~\partial_2 S(x_1,x_1-t_1)+\partial_1S(x_1-t_1,x_1-t_1-t_2)
+\partial_2S(x_1-t_1,x_1-t_1-t_2)\Big),\\
\frac{\partial \Gamma}{\partial t_2}
&=&
\Big(-1,~\partial_2S(x_1-t_1,x_1-t_1-t_2)\Big),
\end{eqnarray*}
where $\partial_kS(x)=\partial_{x_k}S(x_1,x_2)$ for $k=1,2$. Then the Jacobian $J(x,\tau)$ is equal to
\begin{equation*}
J(x,t_1,t_2)=\det
\begin{pmatrix}
{\partial \Gamma/\partial t_1}\\
{\partial \Gamma/\partial t_2}
\end{pmatrix}
=\partial_2S(x_1,x_1-t_1)+\partial_1S(x_1-t_1,x_1-t_1-t_2).
\end{equation*}
By a change of variables, $u=-t_1,\ v=-t_1-t_2$, let
\begin{align*}
F(x,u,v)=J(x,t_1,t_2)
&=\partial_2S(x_1,x_1+u)+\partial_1S(x_1+u,x_1+v).
\end{align*}
Then
$$\partial_vF(x,u,v)
=
\partial_u\partial_v S(x_1+u,x_1+v).$$
Using the factorization $S_{xy}''(x,y)=U(x,y)\prod_{i=1}^N(x-\gamma_i(y))$ with $\gamma_i(0)=0$ and $\gamma_i'(0)=1$, we see that
\begin{equation*}
\partial_u^N\partial_vF(x,u,v)
=\partial_u^N\left(U(x_1+u,x_1+v)
\prod_{i=1}^N(x_1+u-\gamma_i(x_1+v))\right).
\end{equation*}
A direct computation gives $$\partial_u^N\partial_vF(0,u,v)|_{(u,v)=(0,0)}
=N!U(0,0).$$
By continuity, it is true that $\partial_u^N\partial_vF(x,u,v)\neq 0$ for small $x,u,v$. In view of $\partial_{t_1}=(-\partial_u-\partial_v)$ and $\partial_{t_2}=-\partial_v$. It follows immediately that for some $\alpha\in \mathbb{N}^2,|\alpha|=\alpha_1+\alpha_2=N+1$,
$$\partial_{t_1}^{\alpha_1}
\partial_{t_2}^{\alpha_2}J(x,t_1,t_2)\neq 0$$
for all small $x,t_1,t_2$.

If $A_L \geq B_L,$ then by the Phong-Stein Theorem \ref{THM-PS-L2-Regularity},
$$\|Rf\|_{L_{\frac{1}{2(A_L+1)}}^2}\leq C\|f\|_{L^2}.$$
By a complex interpolation, using $\|Rf\|_\infty\leq C\|f\|_\infty,$ we obtain the desired estimate in (i).\\

The proof of (ii) is more intricate. The $L^2$ Sobolev regularity of $Rf$ does not imply the desired result. A resolution of singularities for the Hessian $S_{xy}''$ is necessary to prove various $L^2$ Sobolev regularity estimates.

Assume $S_{xy}''(0,0)=0.$ Then $S(x,y)=\sum_{k,l}a_{k,l}x^k y^l$ is true for small $(x,y)$. By the Puiseux theorem,
$$S_{xy}''(x,y)=U(x,y)x^m y^s\prod_v(y-\gamma_v(x)),$$
where $U(x,y)\neq 0$ is smooth near the origin, $m,s\geq 0$, and $\gamma_v$ are non-trival Puiseux series. Now we shall use the resolution algorithm of $S_{xy}''$ by a complete classification of $\gamma_v$; see Phong-Stein \cite{PS1997}.

The exponents of $\gamma_v$ are ordered as follows:
$$0<a_1<a_2<\cdots<a_l<a_{l+1}<\cdots<a_n.$$
Denote by $\Psi \begin{bmatrix}
\cdot\\
l
\end{bmatrix}$ by the cluster of nonzero roots $\gamma_v$ of the form
\begin{equation}\label{section 7 formula 1}
\gamma_v(x)=C_l^\alpha x^{a_l}+o(x^{a_l}),\ x\rightarrow 0,
\end{equation}
where $C_l^\alpha\neq 0$. For roots $\gamma_v$ associated with a fixed exponent, we consider their coefficients  $C_l^\alpha$, where $\alpha$ is the index for the coefficient of $x^{a_l}$. Let $\Psi\begin{bmatrix}
\cdot\\
l
\end{bmatrix}=\bigcup_\alpha \Psi\begin{bmatrix}
\alpha\\
l
\end{bmatrix}.$
By induction, we continue this classification process to obtain
$$\Psi\begin{bmatrix}
\alpha_1,&\alpha_2,\dots,\alpha_{N-1},&\cdot\\
l_1,& l_2,\dots,l_{N-1},&l_N
\end{bmatrix}=\bigcup_{\alpha_N}\Psi\begin{bmatrix}
\alpha_1,&\alpha_2,&\dots,&\alpha_{N-1},&\alpha_N\\
l_1,&l_2,&\dots,&l_{N-1},&l_N
\end{bmatrix},$$
where the cluster $\Psi \begin{bmatrix}
\alpha_1,&\dots,&\alpha_N\\
l_1,&\dots,&l_N
\end{bmatrix}$ contains all roots of the form
$$\gamma_v(x)
=C_{l_1}^{\alpha_1}x^{a_1}
+C_{l_1,l_2}^{\alpha_1,\alpha_2}x^{a_{l_1,l_2}^{\alpha_1}}
+
\dots+C_{l_1,\dots,l_N}^{\alpha_1,\dots,
\alpha_N}x^{a_{l_1,\cdots,l_N}^{
\alpha_1,\dots,\alpha_{N-1}}}+
o\left(x^{a_{l_1,\cdots,l_N}^{
\alpha_1,\dots,\alpha_{N-1}}}\right).$$
Let $N\begin{bmatrix}
\alpha_1,\dots,\alpha_{k-1},\cdot\\
l_1,\dots,l_{k-1},l_k
\end{bmatrix}$ and $N\begin{bmatrix}
\alpha_1,\dots,\alpha_{k-1},\alpha_k\\
l_1,\dots,l_{k-1},l_k
\end{bmatrix}$ be the number of roots in the cluster $\Psi \begin{bmatrix}
\alpha_1,\dots,\alpha_{k-1},\cdot\\
l_1,\dots,l_{k-1},l_k
\end{bmatrix}$ and
$\Psi \begin{bmatrix}
\alpha_1,\dots,\alpha_{k-1},\alpha_k\\
l_1,\dots,l_{k-1},l_k
\end{bmatrix}$, respectively. For simplicity, we also use the notation
$$N=\sum_{l=1}^n N\begin{bmatrix}
\cdot\\
l
\end{bmatrix}=\sum_{l=1}^N the\ number\ of\ roots\ in\ \Psi\begin{bmatrix}
\cdot\\
l
\end{bmatrix}.$$
The vertices of the Newton polyhedron of $S_{xy}''$ are denoted by $(A_0,B_0),
(A_1,B_1),\cdots,(A_n,B_n)$ with $A_0<A_1<\cdots<A_n$ and $B_0>B_1>\dots>B_n$. Hence
$(A_0,B_0)$ is the leftmost extreme point, also denoted by $(A_L,B_L)$.

It is easy to verify that
$$A_0=m,~~~ B_0=s+\sum_{l=1}^nN\begin{bmatrix}
\cdot\\
l
\end{bmatrix},$$ and for each $1\leq r\leq n$,
$$A_r=m+\sum_{l=1}^rN\begin{bmatrix}
\cdot\\
l
\end{bmatrix}a_l,~~~ B_r=s+\sum_{l=r+1}^mN\begin{bmatrix}
\cdot\\
l
\end{bmatrix}.$$
Choose a smooth cut-off function $\Phi\in C_0^\infty(1/2,2)$ such that $\sum_{j\in \mathbb{Z}}\Phi(x/2^j)=1$ for all $x>0$. Define a localized Radon transform
\begin{equation}\label{Local-daydic-Radon-transform}
R_{j,k}^{\sigma_1,\sigma_2}f(x)
=
\int_{-\infty}^{\infty}f(t+S(x,y),y)
\varphi(x,y)\Phi(\sigma_12^{-j}x)\Phi(\sigma_22^{-k}y)dy,
\end{equation}
where $\sigma_1,\sigma_2\in\{+,-\}$. Here we only consider $R_{j,k}^{\sigma_1,\sigma_2}$ in the first quadrant, i.e., $\sigma_1=\sigma_2=+$. The same argument also works in other quadrants.\\

\noindent\textbf{Case (i).}\quad $k\geq a_1j+N_0$ for a large $N_0\geq 1$.\\

If $m>0$, then
$$|S_{xy}''(x,y)|\approx 2^{mj}2^{(N+s)k}$$
in the support of $R_{j,k}^{\sigma_1,\sigma_2}$. Using the Fourier transform with respect to $t$, we have
$$\widehat{R_{j,k}^{\sigma_1,\sigma_2}f}(\xi,x)
=\int_{-\infty}^{\infty}e^{2\pi i \xi S(x,y)}\hat{f}(\xi,y)\varphi(x,y)
\Phi(\sigma_1 2^{-j}x)\Phi(\sigma_2 2^{-k}y)dy.$$
Then by the van der Corput lemma,
$$\|\widehat{R_{j,k}^{\sigma_1,\sigma_2}f}(\xi,\cdot)\|_2\lesssim \left(|\xi|2^{mj}2^{(N+s)k}\right)^{-1/2}\|\hat{f}(\xi,\cdot)\|_2.$$
Hence, by an interpolation with the trivial size estimate
$$\|\widehat{R_{j,k}^{\sigma_1,\sigma_2}f}(\xi,\cdot)\|_2\lesssim 2^{j/2}2^{k/2}\|f\|_2,$$
we obtain
$$\|\widehat{R_{j,k}^{\sigma_1,\sigma_2}f}(\xi,\cdot)\|_2\lesssim \left(|\xi|2^{(N+s)k}\right)^{-\frac {1}{2(m+1)}}2^{\frac{mk}{2(m+1)}}\|\hat{f}(\xi,\cdot)\|_2.$$
This yields the Sobolev regularity
$$\||\partial_t|^{\frac{1}{2(m+1)}}
R_{j,k}^{\sigma_1,\sigma_2}f\|_2\lesssim 2^{k\delta}\|f\|_2$$
with $\delta$ given by
\begin{equation}\label{section 7 formula 2}
\delta=\frac{m}{2(m+1)}-\frac{N+s}{2(m+1)}.
\end{equation}
By an almost orthogonality argument, we also have
$$\left\|\sum_{j\leq k/a_1+0(1)}\widehat{R_{j,k}^{\sigma_1,
\sigma_2}f}(\xi,\cdot)\right\|_2\lesssim \left(|\xi|2^{(N+s)k}\right)^{-\frac{1}{2(m+1)}}
2^{\frac{mk}{2(m+1)}}\|\widehat{f}(\xi,\cdot)\|_2.$$
Hence
$$\left \||\partial_t|^{\frac{1}{2(m+1)}}\sum_{j\leq k/a_1+N_0/a_1}R_{j,k}^{\sigma_1,\sigma_2}f\right\|_2
\lesssim
2^{k\delta}\|f\|_2,$$
with the exponent $\delta$ given by (\ref{section 7 formula 2}). On the other hand,
$$\left\|\sum_{j\leq k/a_1+N_0/a_1}R_{j,k}f\right\|_\infty
 \lesssim
 2^k\|f\|_\infty.$$
A complex interpolation gives
$$\left\||\partial_t|^{\frac{1}{(m+1)p}}\sum_{j\leq (k-N_0)/a_1}R_{j,k}f\right\|_p
\lesssim
2^{k\delta_p}\|f\|_p,$$
where the exponent $\delta_p$ is defined by
\begin{equation}\label{delta-p}
\delta_p=-\frac{N+s}{m+1}\cdot \frac{1}{p}+\frac{m}{m+1}\cdot\frac{1}{p}+1-\frac{2}{p}
=1-\frac{m+N+s+2}{(m+1)p}>0
\end{equation}
if $p>\frac{A_L+B_L+2}{A_L+1}=\frac{m+N+s+2}{m+1}$.
This proves
$$\sum_{k\geq 0}\Big\||\partial_t|^{\frac{1}{(m+1)p}}
\sum_{j\ll k_1/a_0}R_{j,k}f\Big\|_p\lesssim \|f\|_p,~~~ p>\frac{A_L+B_L+2}{A_L+1}.$$
The case $m=0$ can be proved similarly without almost orthogonality argument. Consider
$$R_k^{\sigma_1,\sigma_2}
=
\sum_{j\ll k_1/a_1}R_{j,k}^{\sigma_1,\sigma_2}.$$
Then, by an interpolation of the oscillation and size estimates,
$$\|\widehat{R_k^{\sigma_1,\sigma_2}f}(\xi,\cdot)\|_2
\lesssim
\left(|\xi|2^{(N+s)k}\right)^{-\frac{1}{2}}
\|\widehat{f}(\xi,\cdot)\|_2$$
and
$$\||\partial_t|^{1/2}R_k^{\sigma_1,\sigma_2}f\|_2
\lesssim
2^{-(N+s)k/2}\|f\|_2.$$
In view of the size estimate
$$\|R_k^{\sigma_1,\sigma_2} f\|_\infty
\lesssim
2^k\|f\|_\infty.$$
It follows immediately that
$$\left\||\partial_t|^{\frac{1}{(m+1)p}}
R_k^{\sigma_1,\sigma_2}f\right\|_p
\lesssim
2^{k\delta_p}\|f\|_p,~~~ p>\frac{A_L+B_L+2}{A_L+1}$$
with $\delta_p>0$. This also implies the desired estimate.

A similar argument can be used to prove the regularity with respect to $x$, i.e.,
$$\int_{\xi \in \mathbb{R}}\int_{h\in \mathbb{R}}\int_{x\in \mathbb{R}}
\frac{|\widehat{R_k^{\sigma_1,\sigma_2}f}(\xi,x+h)
-\widehat{R_k^{\sigma_1,\sigma_2}f}(\xi,x)|^2}
{|h|^{1+\frac{1}{m+1}}}dxdhd\xi
\lesssim 2^{\frac{m-N-s}{m+1}k}\|\widehat{f}(\xi,\cdot)\|_2^2.$$
By interpolation, we obtain
$$\left\||\partial_x|^{\frac{1}{(A_L+1)p}}
R_k^{\sigma_1,\sigma_2} f\right\|_p
\lesssim
2^{k\delta_p}\|f\|_p,~~~ p>\frac{A_L+B_L+2}{A_L+1},$$
where $\delta_p$ is defined as in (\ref{delta-p}). Since $\delta_p$ is positive, we obtain the desired estimate by taking summation over $k$.\\

\noindent\textbf{Case 2.}\quad $k\leq a_nj-N_0$ for some large $N_0>0$.\\

Consider first the case $s>0$. On the support of $R_{j,k}^{\sigma_1,\sigma_2}$,
$$|S_{xy}''(x,y)|\approx 2^{mj}2^{sk}2^{j\sum_{l=1}^N N\begin{bmatrix}
\begin{smallmatrix}
\cdot\\ l
\end{smallmatrix}
\end{bmatrix}a_l}.$$
The partial Fourier transform $\widehat{R_{j,k}^{\sigma_1,\sigma_2}f}(\xi,\cdot)$ satisfies
$$\|\widehat{R_{j,k}^{\sigma_1,\sigma_2}f}(\xi,\cdot)\|_2
\lesssim
\left(|\xi|2^{mj}2^{sk}2^{j\sum_{l=1}^n N\begin{bmatrix}
\begin{smallmatrix}
\cdot\\ l
\end{smallmatrix}
\end{bmatrix}a_l}\right)^{-1/2}
\|\widehat{f}(\xi,\cdot)\|_2$$
and
$$\|\widehat{R_{j,k}f}(\xi,\cdot)\|_2\lesssim 2^{\frac{j}{2}}2^{\frac{k}{2}}
\|\widehat{f}(\xi,\cdot)\|_2.$$

Let $\theta=\frac{1}{m+1}$. A convex combination of the above two estimates gives
\begin{equation}\label{section 7 formula 3}
\|\widehat{R_{j,k}^{\sigma_1,\sigma_2}f}(\xi,\cdot)\|_2
\lesssim
\left(|\xi|2^{mj}2^{sk}2^{j\sum_{l=1}^N N\begin{bmatrix}
\begin{smallmatrix}
\cdot\\ l
\end{smallmatrix}
\end{bmatrix}a_l}\right)^{-\frac{\theta}{2}}2^{\frac{j}{2}(1-\theta)}2^{\frac{k}{2}(1-\theta)}
\|\hat{f}(\xi,\cdot)\|_2.
\end{equation}
The gives the estimate for $\||\partial_t|^{\frac{1}{2(m+1)}}
R_{j,k}^{\sigma_1,\sigma_2}f\|_2.$ With $\|R_{j,k}^{\sigma_1,\sigma_2}f\|_\infty\lesssim 2^k\|f\|_\infty$, an interpolation gives
\begin{equation}\label{section 7 formula 4}
\left\||\partial_t|^{\frac{1}{(m+1)p}}
R_{j,k}^{\sigma_1,\sigma_2}f\right\|_p
\lesssim
2^{j\delta_1}2^{k\delta_2}\|f\|^p,~~~ 2\leq p< +\infty,
\end{equation}
where $\delta_1$ and $\delta_2$ are given by
$$\delta_1=-\left(m+\sum_{l=1}^n N\begin{bmatrix}
\cdot\\
l
\end{bmatrix}a_l\right)\cdot \frac{\theta}{p}+\frac{1-\theta}{p},$$
$$\delta_2=-\frac{s\theta}{p}+\frac{1-\theta}{p}+1-\frac{2}{p}.$$
If $p>\frac{A_L+B_L+2}{A_L+1},$ then
$\delta_2=1-\frac{s+m+2}{(m+1)p}>0,\ A_L=m,\ B_L=s+\sum_{l=1}^nN\begin{bmatrix}
\begin{smallmatrix}
\cdot\\ l
\end{smallmatrix}
\end{bmatrix}.$
If we take the summation of (\ref{section 7 formula 4}) over $k\leq a_nj-N_0$, then the desired estimate is true provided that $\delta_1+a_n\delta_2>0$. Now we shall verify this simple observation. To see this, observe
\begin{align*}
\delta_1+a_n\delta_2&=-\left(m+\sum_{l=1}^n N
\begin{bmatrix}
\cdot\\
l
\end{bmatrix}a_l\right)\cdot \frac{1}{(m+1)p}+\frac{m}{(m+1)p}+a_n-\frac{(s+m+2)a_n}{(m+1)p}\\
&\geq a_n-a_n\left(s+m+2+\sum_{l=1}^n N
\begin{bmatrix}
\cdot\\ l
\end{bmatrix}\right)\frac{1}{(m+1)p}\\
&=a_n-a_n\frac{A_L+B_L+2}{(A_L+1)p}>0
\end{align*}
for $p>\frac{A_L+B_L+2}{A_L+1}$.
If $s=0$, we consider $R_j^{\sigma_1,\sigma_2}
=\sum_{k:k\leq a_nj-N_0}R_{j,k}^{\sigma_1,\sigma_2}$ instead of each piece $R_{j,k}^{\sigma_1,\sigma_2}$. The estimate for
$R_j^{\sigma_1,\sigma_2}$ is also true, similar to the case $s>0$,
$$\left\||\partial_t|^{\frac{1}{(m+1)p}}
R_j\sigma_1 f\|_p
\lesssim
2^{j(\delta_1+a_n\delta_2)}\right\|f\|_p,~~~ p>\frac{A_L+B_L+2}{A_L+1}.$$
The convergence of the summation over $j\leq 0$ implies the desired estimate.

Now consider the corresponding estimate for the variable $x$. Assume first $s>0$. Then
\begin{eqnarray}\label{section 7 formula 5}
& &
\widehat{R_{j,k}^{\sigma_1,\sigma_2}f}(\xi,x+h)
-\widehat{R_{j,k}^{\sigma_1,\sigma_2}f}(\xi,x)\nonumber\\
&=&
\int_{\mathbb{R}}\left(e^{2\pi i \xi[S(x+h,y)-S(x,y)]}-1\right)e^{2\pi i \xi S(x,y)}\hat{f}(\xi,y)\eta_{j,k}(x+h,y)dy \nonumber\\
& &
+\int_{\mathbb{R}}e^{2\pi i \xi S(x,y)}\hat{f}(x,y)\left(
\eta_{j,k}^{\sigma_1,\sigma_2}(x+h,y)
-
\eta_{j,k}^{\sigma_1,\sigma_2}(x,y)\right)dy,
\end{eqnarray}
where $\eta_{j,k}^{\sigma_1,\sigma_2}(x,y)
=\Phi(\sigma_1x/2^j)\Phi(\sigma_2y/2^k)\varphi(x,y)$. We shall prove that
$\||\partial_x|^{\frac{1}{2(m+1)}}
R_{j,k}^{\sigma_1,\sigma_2}f\|_2$ has the same bound as in (\ref{section 7 formula 4}).

If the integral of $h$ is restricted to $|h\xi|>1$, then we apply (\ref{section 7 formula 3}) to get
\begin{align*}
&\int_{\mathbb{R}}\int_{|h\xi|>1}\int_{\mathbb{R}}
\frac{|\widehat{R_{j,k}^{\sigma_1,\sigma_2}f}(\xi,x+h)-
\widehat{R_{j,k}^{\sigma_1,\sigma_2}f}(\xi,x)|^2}
{|h|^{1+\frac{1}{m+1}}}dxdhd\xi \\
\leq &2\int_{\mathbb{R}}\int_{|h\xi|>1}
|h|^{-1-\frac{1}{m+1}}\|\widehat{f}(\xi,\cdot)\|_2^2
\left(|\xi|~2^{sk}2^{j\sum_{l=1}^{n}N
\begin{bmatrix}
\begin{smallmatrix}
\cdot\\ l
\end{smallmatrix}
\end{bmatrix}a_l
}\right)^{-\frac{1}{m+1}}
2^{\frac{mk}{m+1}}dhd\xi\\
\lesssim &\left(2^{sk}2^{j\sum_{l=1}^n N
\begin{bmatrix}
\begin{smallmatrix}
\cdot\\ l
\end{smallmatrix}
\end{bmatrix}a_l}\right)^{-\frac{1}{m+1}}
2^{\frac{mk}{m+1}}
\|f\|_2^2.
\end{align*}
This bound is the same as that of (\ref{section 7 formula 4}) for $p=2$.

For the integral restricted to $|h\xi|\leq 1$, we write the right hand side of (\ref{section 7 formula 5}) as $E_{j,k}^{\sigma_1,\sigma_2}+F_{j,k}^{\sigma_1,\sigma_2}$. By the operator van der Corput lemma, we obtain
$$\int_{\mathbb{R}}|E_{j,k}^{\sigma_1,\sigma_2}|^2dx
\lesssim |h\xi|^2\left(|\xi|~2^{sk}2^{\sum_{l=1}^nN
\begin{bmatrix}
\begin{smallmatrix}
\cdot\\ l
\end{smallmatrix}
\end{bmatrix}a_l}\right)^{-\frac{1}{m+1}}
2^{\frac{mk}{m+1}}
\|\widehat{f}(\xi,\cdot)\|_2.$$
Hence
$$\int_{\mathbb{R}}\int_{|h\xi|<1}
\int_{\mathbb{R}}
\frac{|E_{j,k}^{\sigma_1,\sigma_2}|^2}{|h|^{1+\frac
{1}{m+1}}}dxdhd\xi
\lesssim
\left(2^{sk}2^{\sum_{l=1}^nN\begin{bmatrix}
\begin{smallmatrix}
\cdot\\ l
\end{smallmatrix}
\end{bmatrix}a_l}\right)^{-\frac{1}{m+1}}
2^{\frac{mk}{m+1}}
\|f\|_2^2.$$
As expected, this estimate is the same as (\ref{section 7 formula 4}) for $p=2$. For $F_{j,k}$, the oscillation estimate shall be replaced by the size estimate, using the Cauchy-Schwarz inequality,
$$\int_{\mathbb{R}}|F_{j,k}^{\sigma_1,\sigma_2}|^2dx
\lesssim
\,{\rm min} \left\{\left(\frac{|h|}{2^j}\right)^2,1\right\}2^j 2^k\|\widehat{f}(\xi,\cdot)\|_2^2.$$
A simple observation is
$$\int_{\mathbb{R}}|h|^{-1-\frac{1}{m+1}}\,{\rm min} \left\{\left(\frac{|h|}{2^j}\right)^2,1\right\}dh \lesssim 2^{-\frac{j}{m+1}}.$$
As a consequence, we obtain
$$\int_{\mathbb{R}}\int_{\mathbb{R}}\int_{\mathbb{R}}
|F_{j,k}^{\sigma_1,\sigma_2}|^2dxdhd\xi\lesssim
2^{mj/(m+1)}2^k\|f\|_2^2.$$
Interpolation with the trivial estimate $\|R_{j,k}f\|_\infty\lesssim 2^k\|f\|_\infty$ gives
$$\left\||\partial_x|^{\frac{1}{2(m+1)}}
R_{j,k}^{\sigma_1,\sigma_2}f\right\|_p
\lesssim A_{j,k}\|f\|_p,~~~ p>\frac{A_L+B_L+2}{A_L+1},$$
where $A_{j,k}$ satisfies $\sum_{j\leq 0}\sum_{k\leq a_nj-N_0}A_{j,k}<+\infty$.\\

\noindent\textbf{Case 3.}\quad $k=a_{t_1}j+O(1)$ for some $1\leq t_1 \leq n$.\\

Consider first $a_{t_1}\geq 1$. The inequality $|k-a_{t_1}j|\leq N_0$ implies that the zeros of $S_{xy}''$, on the support of $R_{j,k}^{\sigma_1,\sigma_2}$, are of form $y=cx^{a_{t_1}}+o(x^{a_{t_1}})$.
For this reason, we insert $\Phi(\sigma_3(y-C_{t_1}^{\alpha_1}x^{a_{t_1}})/2^{\mu_1})$ into the cut-off function of $R_{j,k}^{\sigma_1,\sigma_2}$. The resulting operator is denoted by $R_{j,k,\mu_1}^{\sigma_1,\sigma_2,\sigma_3}$, with smaller support.
If $\mu_1$ satisfies $\mu_1\geq k-N_0$ for some large $N_0$, then the zeros of the Hessian are far away from $y=C_{t_1}^{\alpha_1}x^{a_{t_1}}+o(x^{a_{t_1}})$.
Then choose another index $\alpha_1'\neq \alpha_1$ and further decompose $R_{j,k,\mu_1}^{\sigma_1,\sigma_2,\sigma_3}$ into smaller pieces $R_{j,k,\mu_1,\mu_2}^{\sigma_1,\sigma_2,\sigma_3,\sigma_4}$ by insertion of $\Phi(\sigma_4(y-C_{t_1}^{\alpha_1'}x^{a_{t_1}})/2^{\mu_2})$ into the cut-off function of $R_{j,k,\mu_1}^{\sigma_1,\sigma_2,\sigma_3}$. \\


For example, we consider $\mu_1\ll k$. For points in the support of $R_{j,k,\mu_1}^{\sigma_1,\sigma_2,\sigma_3}$, $$\left|y-C_{t_1}^{\alpha}x^{a_{t_1}}\right|\approx 2^k$$
for $\alpha\neq \alpha_1$. To further decompose $R_{j,k,\mu_1}^{\sigma_1,\sigma_2,\sigma_3}$ into smaller pieces, it is convenient to divide the range of $\mu_1$ into several cases:
\begin{enumerate}
\item[{\rm (i)}] $a_{t_1,1}^{\alpha_1}j\ll \mu_1\ll a_{t_1}j$;
\item[{\rm (ii)}] $a_{t_1,t+1}^{\alpha_1}j\ll \mu_1\ll a_{t_1,t}^{\alpha_1}j,\quad 1\leq t\leq {N}\begin{bmatrix}
    \begin{smallmatrix}
\alpha_1\\
t_1
\end{smallmatrix}
\end{bmatrix}-1$;
\item[{\rm (iii)}] $\mu_1\ll a_{t_1,t}^{\alpha_1}j$ with $t={N}\begin{bmatrix}
    \begin{smallmatrix}
\alpha_1\\
t_1
\end{smallmatrix}
\end{bmatrix}$;
\item[{\rm (iv)}] $\mu_1=a_{t_1,t}^{\alpha_1}j + O(1)$
for some $1\leq t\leq {N}\begin{bmatrix}
\begin{smallmatrix}
\alpha_1\\
t_1
\end{smallmatrix}
\end{bmatrix}$.
\end{enumerate}
For the previous three cases, the Hessian of the phase function behaves like a nonzero constant. We turn to the most delicate case  (iv). More precisely, we assume
$\left|\mu_1-a_{t_1,t_2}^{\alpha_1}j\right|\lesssim 1$. By insertion of the cut-off function $$\Phi(\sigma_4(y-C_{t_1}^{\alpha_1}x^{a_{t_1}}
-C_{t_1,t_2}^{\alpha_1,\alpha_2}
x^{a_{t_1,t_2}^{\alpha_1}})/{2^{\mu_2}}),$$
we decompose $R_{j,k,\mu_1}^{\sigma_1,\sigma_2,\sigma_3}$ into smaller pieces $R_{j,k,\mu_1,\mu_2}^{\sigma_1,\sigma_2,\sigma_3,\sigma_4}$. For the same reason, we may assume $\mu_2\ll \mu_1$
such that for $\alpha\neq \alpha_2$,
$
|y-C_{t_1}^{\alpha_1}x^{a_{t_1}}
-C_{t_1,t_2}^{\alpha_1,\alpha}x^{a_{t_1,t_2}^{\alpha_1}}|\approx 2^{\mu_1}
$
in the support of $R_{j,k,\mu_1,\mu_2}^{\sigma_1,\sigma_2,\sigma_3,\sigma_4}$.\\

By induction, if $R_{j,k,\mu_1,\cdots,\mu_p}^{\sigma_1,\sigma_2,
\cdots,\sigma_{p+2}}$ has been defined and $\mu_p$ lies in the range
$\mu_p=a_{t_1,\cdots,t_{p+1}}^{\alpha_1,\cdots,\alpha_p}j
+O(1),$
we choose $\alpha_{p+1}$ and insert
$$
\Phi\Big(\sigma_{p+3}(y
-\sum_{i=1}^{p+1}C_{t_1,\cdots,t_{i}}^{\alpha_1,
\cdots,\alpha_i}
x^{a_{t_1,\cdots,t_i}^{\alpha_1,
\cdots,\alpha_{i-1}}})/{2^{\mu_{p+1}}}\Big)
$$
into the cut-off function of $R_{j,k,\mu_1,\cdots,\mu_{p}}^{\sigma_1,
\cdots,\sigma_{p+2}}$. In this way, we obtain a new operator $R_{j,k,\mu_1,\cdots,\mu_{p+1}}^{\sigma_1,\cdots,
\sigma_{p+3}}$. Similar to our discussion for $\mu_1$, there are also four possible ranges for $\mu_{p+1}$.\\

Assume the above procedure stops in the $N$-th step. Then $\mu_N$ must satisfy one of the following conditions:
\begin{enumerate}
\item[{\rm (i)}] $a_{t_1,\cdots,t_N,1}^{\alpha_1,\cdots,\alpha_N}j\ll \mu_N\ll \mu_{N-1}$;
\item[{\rm (ii)}] $a_{t_1,\cdots,t_N,t_{N+1}+1}^{\alpha_1,\cdots,\alpha_N}j\ll \mu_N\ll a_{t_1,\cdots,t_{N+1}}^{\alpha_1,\cdots,\alpha_N}j$ for some
    $1\leq t_{N+1}\leq \textbf{N}\begin{bmatrix}
\begin{smallmatrix}
\alpha_1,\cdots,\alpha_N\\
t_1,\cdots,t_N
\end{smallmatrix}
\end{bmatrix}-1$ and\\
$1\leq \alpha_N\leq \textbf{N}\begin{bmatrix}
\begin{smallmatrix}
\alpha_1,\cdots,\alpha_{N-1}, \cdot\\
t_1,\cdots,t_{N-1}, t_N
\end{smallmatrix}
\end{bmatrix}$;
\item[{\rm (iii)}] $\mu_N\ll a_{t_1,\cdots,t_{N+1}}^{\alpha_1,\cdots,\alpha_N}j$ with $t_{N+1}=\textbf{N}\begin{bmatrix}
\begin{smallmatrix}
\alpha_1,\cdots,\alpha_N\\
t_1,\cdots,t_N
\end{smallmatrix}
\end{bmatrix}$;
\item[{\rm (iv)}] For some $t$ we have $\mu_N= a_{t_1,\cdots,t_N,t}^{\alpha_1,\cdots,\alpha_N}j + O(1)$, and for all $\alpha$
\begin{equation*}
\Big|y-\sum_{i=1}^N C_{t_1,\cdots,t_i}^{\alpha_1,\cdots,\alpha_{i}} x^{a_{t_1\cdots t_i}^{\alpha_1\cdots\alpha_{i-1}}}
-
C_{t_1,\cdots,t_N,t}^{\alpha_1,\cdots,
\alpha_N,\alpha} x^{a_{t_1\cdots t_N,t}^{\alpha_1\cdots\alpha_N}}\Big|
\approx
2^{\mu_N},~~~(x,y)\in\,{\rm supp}\,(R_{j,k,\mu_1,
\cdots,\mu_N}^{\sigma_1,\cdots,\sigma_{N+2}}).
\end{equation*}
\end{enumerate}

Consider the case (ii) for $\mu_N$. Other cases can be treated in the same way. Now we shall prove the Sobolev estimate for $R_{j,k,\mu_1,\cdots,\mu_{N+1}}^{\sigma_1,\cdots,
\sigma_{N+3}}$. By the van der Corput lemma,
\begin{align}\label{general-L2-osc-est}
&\|\widehat{R_{j,k,\mu_1,\cdots,\mu_{N+1}}^{\sigma_1,
\cdots,
\sigma_{N+3}}f}(\xi,\cdot)\|_2
\lesssim  \nonumber\\
&\Bigg[|\xi|2^{jA_{t_1-1}}2^{kB_{t_1}}
\prod_{\alpha\neq \alpha_1}2^{k\textbf{N}\begin{bmatrix}
\begin{smallmatrix}
\alpha\\
t_1
\end{smallmatrix}
\end{bmatrix}}
\prod_{l<t_2}2^{\textbf{N}\begin{bmatrix}
\begin{smallmatrix}
\alpha_1,\cdot\\
t_1,l
\end{smallmatrix}
\end{bmatrix}a_{t_1,l}^{\alpha_1}j}
\prod_{l>t_2}2^{\textbf{N}\begin{bmatrix}
\begin{smallmatrix}
\alpha_1,\cdot\\
t_1,l
\end{smallmatrix}
\end{bmatrix}\mu_1}
\prod_{\alpha\neq\alpha_2}2^{\mu_1\textbf{N}
\begin{bmatrix}
\begin{smallmatrix}
\alpha_1,\alpha\\
t_1,t_2
\end{smallmatrix}
\end{bmatrix}}\cdots  \nonumber  \\
&\prod_{l\leq t_{N+1}}2^{j\textbf{N}\begin{bmatrix}
\begin{smallmatrix}
\alpha_1,\cdots,\alpha_N,\cdot\\
t_1,\cdots,t_N,l
\end{smallmatrix}
\end{bmatrix}a_{t_1,\cdots,t_N,l}^{\alpha_1,\cdots,
\alpha_N}}\prod_{l> t_{N+1}}2^{\textbf{N}
\begin{bmatrix}
\begin{smallmatrix}
\alpha_1,\cdots,\alpha_N,\cdot\\
t_1,\cdots,t_N,l
\end{smallmatrix}
\end{bmatrix}\mu_N}\Bigg]^{-1/2} \|\widehat{f}(\xi,\cdot)\|_2.
\end{align}

\noindent The size estimate gives
\begin{equation}\label{general-size-estimate}
\|\widehat{R_{j,k,\mu_1,\cdots,\mu_{N+1}}^{\sigma_1,
\cdots,
\sigma_{N+3}}f}(\xi,\cdot)\|_2
\lesssim 2^{\mu_N/2}\left(2^{\mu_N}2^{-j(a_{t_1}-1)}\right)^{1/2}
\|\widehat{f}(\xi,\cdot)\|_2.
\end{equation}
By the almost orthogonality principle, both of the above estimates are still true for
$\sum R_{j,k,\mu_1,\cdots,\mu_{N+1}}^{\sigma_1,
\cdots,\sigma_{N+3}}f$, where the summation is taken over $j,k,\mu_1,\mu_2,\cdots,\mu_{N}$.

Since $\mu_N\leq \,{\rm min}\{j/{a_{t_1}},k,\mu_1,\cdots,\mu_{N-1}\}+O(1)$, a convex combination of the above two inequalities yields
\begin{equation}\label{L2-Sob-reg-general-pieces}
\Big\||\partial_t|^{\frac{1}{2(m+1)}}\sum{R_{j,k,\mu_1,\cdots,\mu_{N+1}}^{\sigma_1,
\cdots,
\sigma_{N+3}}f}\Big\|_2
\lesssim
2^{\delta}\|f\|_2,
\end{equation}
where the exponent is given by
\begin{equation*}
\delta
=
\frac{m\mu_N}{2(m+1)}
-\frac{\mu_N}{2(m+1)}
\left(s+\sum_{l=1}^{t_1-1}
{N}
\begin{bmatrix}
\begin{smallmatrix}
\cdot\\ l
\end{smallmatrix}
\end{bmatrix}a_l/a_{t_1}
+
\sum_{l=t_1}^n{N}
\begin{bmatrix}
\begin{smallmatrix}
\cdot\\ l
\end{smallmatrix}
\end{bmatrix}\right).
\end{equation*}
It is easy to see that
\begin{equation*}
\left\|\sum{R_{j,k,\mu_1,\cdots,\mu_{N+1}}^{\sigma_1,
\cdots,
\sigma_{N+3}}f}\right\|_{\infty}
\lesssim
2^{\mu_N}\|f\|_{\infty}.
\end{equation*}
An interpolation yields
\begin{equation}\label{Lp-Sobolev-regu-est}
\Big\||\partial_t|^{\frac{1}{(m+1)p}}
\sum{R_{j,k,\mu_1,\cdots,\mu_{N+1}}^{\sigma_1,
\cdots,
\sigma_{N+3}}f}\Big\|_p
\lesssim
2^{\rho\mu_N}\|f\|_p,
\end{equation}
with
\begin{eqnarray*}
\rho
&=&
1-\frac{m+2+\left(s+\sum_{l=1}^{t_1}
{N}
\begin{bmatrix}
\begin{smallmatrix}
\cdot\\ l
\end{smallmatrix}
\end{bmatrix}a_l/a_{t_1}
+
\sum_{l=t_1+1}^n{N}
\begin{bmatrix}
\begin{smallmatrix}
\cdot\\ l
\end{smallmatrix}
\end{bmatrix}\right)}{(m+1)p}\\
&\geq&
1-\frac{m+2+s+\sum_{l=1}^{n}
{N}
\begin{bmatrix}
\begin{smallmatrix}
\cdot\\ l
\end{smallmatrix}
\end{bmatrix}}
{(m+1)p}\\
&=&
1-
\frac{A_{L}+B_{L}+2}{(A_L+1)p}.
\end{eqnarray*}
Here we use the assumption $a_{t_1}\geq 1$. It is clear that $\rho>0$ for $p>\frac{A_{L}+B_{L}+2}{A_L+1}$. Taking the summation over $\mu_N$, we get the desired $L^p$ Sobolev regularity estimate in the variable $t$.\\

For the variable $x$, we shall establish the corresponding Sobolev regularity. Write
\begin{eqnarray*}
& &
\widehat{R_{j,k,\mu_1,\cdots,
\mu_{N+1}}^{\sigma_1,\cdots,\sigma_{N+3}}f}(\xi,x+h)
-
\widehat{R_{j,k,\mu_1,\cdots,
\mu_{N+1}}^{\sigma_1,\cdots,\sigma_{N+3}}f}(\xi,x)\\
&=&
\int_{\mathbb{R}}\left(e^{2\pi i \xi[S(x+h,y)-S(x,y)]}-1\right)e^{2\pi i \xi S(x,y)}\hat{f}(\xi,y)\eta_{j,k,\mu_1,\cdots,
\mu_{N+1}}^{\sigma_1,\cdots,\sigma_{N+3}}(x+h,y)dy\\
& &
+\int_{\mathbb{R}}e^{2\pi i \xi S(x,y)}\hat{f}(x,y)
\left(\eta_{j,k,\mu_1,\cdots,
\mu_{N+1}}^{\sigma_1,\cdots,\sigma_{N+3}}(x+h,y)
-
\eta_{j,k,\mu_1,\cdots,
\mu_{N+1}}^{\sigma_1,\cdots,\sigma_{N+3}}(x,y)\right)dy\\
&=:&
E_{j,k,\mu_1,\cdots,
\mu_{N+1}}^{\sigma_1,\cdots,\sigma_{N+3}}
+
F_{j,k,\mu_1,\cdots,
\mu_{N+1}}^{\sigma_1,\cdots,\sigma_{N+3}},
\end{eqnarray*}
where $\eta_{j,k,\mu_1,\cdots,
\mu_{N+1}}^{\sigma_1,\cdots,\sigma_{N+3}}
$ is the cut-off function of $R_{j,k,\mu_1,\cdots,
\mu_{N+1}}^{\sigma_1,\cdots,\sigma_{N+3}}$. One can verify that
\begin{equation*}
\int_{\mathbb{R}}\int_{|h\xi|>1}\int_{\mathbb{R}}
\frac{|\widehat{R_{j,k,\mu_1,\cdots,
\mu_{N+1}}^{\sigma_1,\cdots,\sigma_{N+3}}f}(\xi,x+h)
-
\widehat{R_{j,k,\mu_1,\cdots,
\mu_{N+1}}^{\sigma_1,\cdots,\sigma_{N+3}}f}(\xi,x)|^2}
{|h|^{1+\frac{1}{m+1}}}dxdhd\xi
\lesssim
2^{2\delta}
\|f\|_2^2
\end{equation*}
with the same $\delta$ as in (\ref{L2-Sob-reg-general-pieces}).
Also, the following is true:
\begin{equation*}
\int_{\mathbb{R}}\int_{|h\xi|\leq 1}\int_{\mathbb{R}}
\frac{|E_{j,k,\mu_1,\cdots,
\mu_{N+1}}^{\sigma_1,\cdots,\sigma_{N+3}}|^2}
{|h|^{1+\frac{1}{m+1}}}dxdhd\xi
\lesssim
2^{2\delta}
\|f\|_2^2
\end{equation*}
with the same exponent as above. On the other hand, by the Cauchy-Schwarz inequality, we have
\begin{equation*}
\int_{\Bbb R}
|F_{j,k,\mu_1,\cdots,
\mu_{N+1}}^{\sigma_1,\cdots,\sigma_{N+3}}|^2dx
\lesssim
\,{\rm min}\left\{\left(\frac{2^{j(a_{t_1}-1)}}{2^{\mu_N}}
|h|\right)^2,
1\right\} 2^{\mu_N-j(a_{t_1}-1)}
2^{\mu_N}\|\widehat{f}(\xi,\cdot)\|_2^2.
\end{equation*}
This implies
\begin{eqnarray*}
\int_{\Bbb R^3}
|F_{j,k,\mu_1,\cdots,
\mu_{N+1}}^{\sigma_1,\cdots,\sigma_{N+3}}|^2dxdhd\xi
&\lesssim&
2^{\mu_N/(m+1)-j(a_{t_1}-1)/(m+1)}
2^{\mu_N-j(a_{t_1}-1)}
2^{\mu_N}\|f\|_2^2
\lesssim
2^{2\delta}\|f\|_2^2
\end{eqnarray*}
with the same $\delta$ as above. The almost orthogonality is also true since all of the above estimates are taken first with respect to $x$. Hence (\ref{Lp-Sobolev-regu-est}) also holds with $\partial_t$
replaced by $\partial_x$.

It remains to consider $0<a_{t_1}<1$ in Case 3, . If $0<a_{t_1}<1$ then our argument needs some modifications. Since $S$ is a real-analytic function, we can write
\begin{equation}\label{sec3 conjuate invariant product}
\prod_{r_{\nu}\in \Psi\begin{bmatrix}
\begin{smallmatrix}
\cdot\\
t_1
\end{smallmatrix}
\end{bmatrix}}(y-r_\nu(x))=V(x,y)\prod(x-h(y)),
\end{equation}
where $V$ is non-vanishing function near the origin, $h(y)$ is a Puiseux series in $y$ of the form
\[
h(y)=d_{l_1}^{\alpha_1}y^{b_{l_1}}
+d_{l_1,l_2}^{\alpha_1,\alpha_2}y^{b_{l_1,l_2}^{\alpha_1}}
+\cdots+d_{l_1,\cdots,l_N}^{\alpha_1,\cdots,\alpha_N}
y^{b_{l_1,\cdots,l_N}^{\alpha_1,\cdots,\alpha_{N-1}}}
+o(y^{b_{l_1,\cdots,l_N}^{\alpha_1,\cdots,\alpha_{N-1}}}),~~~
b_{l_1}=\frac{1}{a_{t_{1}}}.\]
By the symmetry of $x$ and $y$ in our resolution of singularities, the above argument also works in the case $0<a_{t_1}<1$.

Combining all above results, we complete the proof of the theorem.

{\rm (\cite{yangchanwoo2})} Assume $S$ is a real analytic function in a small neighborhood of the origin in $\mathbb{R}^2$. Suppose the reduced Newton polyhedron of $S$ has at least two extreme points. Let $(A_0,B_0),
(A_1,B_1),\dots,(A_n,B_n)$ are extreme points of $N_r(S)$ with $A_0<A_1<\dots<A_n$ and $B_0>B_1>\dots>B_n$. If $S$ is not of the form in the above case {\rm (ii)}, then the following integral operator
\begin{equation*}
Tf(x)=\int_{-\epsilon_0}^{\epsilon_0}
|S_{xy}''(x,y)|^{z}
f(y)dy,~~~\,{\rm Re}\,(z)=-\frac{1}{A_{\theta}+B_{\theta}-2},
\end{equation*}
is bounded on $L^{p_{\theta}}$ for every small number $\epsilon_0>0$, where $A_{\theta}=\theta A_{k-1}+(1-\theta)A_k$, $B_{\theta}=\theta B_{k-1}+(1-\theta)B_k$, and $p_{\theta}=
\frac{A_{\theta}+B_{\theta}-2}{A_{\theta}-1}$ for some $\theta\in (0,1)$ and $1\leq k \leq n$.

\label{Thm-SRT-Hilbert-Transform}
Assume $S$ is a real-valued and real-analytic function near the origin in the plane, and its Hessian $S''_{xy}$ can be written as
\begin{equation*}
S''_{xy}(x,y)=U(x,y)\prod_{i=1}^{N}(x-r_i(y)),
\end{equation*}
where $U(x,y)\neq0$ near the origin, $N\geq 1$, $r_i$ are convergent Puiseux series in a small interval $(-\epsilon,\epsilon)$, $r_i(0)=0$, and $r_i'(0)=1$. Let $\mathbf{R}$ and $\mathbf{M}$ be defined by
\begin{eqnarray*}
\mathbf{R}f(t,x)
&=&
\int_{\Bbb R}f(t+S(x,x-y),x-y)
\frac{z}{|y|^{z+1}}\varphi(t,x,y)dy,
~~~\,{\rm Re}\,(z)=0,\\
\mathbf{M}f(t,x)
&=&
\sup_{0<h<\epsilon}\frac{1}{2h}\int_{-h}^{h}
|f(t+S(x,x-y),x-y)|dy,~~~|t|<\epsilon,|x|<\epsilon,
\end{eqnarray*}
where $\varphi$ is a smooth cut-off function near the origin in $\Bbb R^3$. Then $\mathbf{R}$ and $\mathbf{M}$ are bounded on $L^p(\Bbb R^2)$ for $1<p<\infty$. Moreover, let
\begin{eqnarray*}
\mathbf{R^{\ast}}f(x)
&=&
\sup_{\epsilon>0}\left|\int_{|t|\geq \epsilon}f(t+S(x,x-y),x-y)
\frac{z}{|y|^{z+1}}\varphi(t,x,y)dy \right|,
~~~\,{\rm Re}\,(z)=0.
\end{eqnarray*}
Then $\mathbf{R^{\ast}}$ is also bounded on $L^p$ for $1<p<\infty$.

By Fourier expansion, we shall replace the smooth cut-off $\varphi(t,x,y)$ by $\varphi(t,x)\chi_{I_{\epsilon_0}}(y)$ for a small $\epsilon_0>0$, where $I_{\epsilon_0}=(-\epsilon_0,\epsilon_0)$ and $\chi_{I_{\epsilon_0}}$ is the characteristic function of $I_{\epsilon_0}$. Write $z=i\omega$ with $\omega\in\mathbb{R}$. Let $\epsilon_j=\exp(-\frac{2j\pi}{|\omega|})$ for large $j\in \mathbb{N}$. Define ${T}_j$ by
\begin{equation}\label{Def-Tj-II}
{T}_jf(t,x)
=
\varphi(t,x)\int_{\epsilon_{j+1}<|y|<\epsilon_j}f(t+S(x,x-y),x-y)
\frac{z}{|y|^{z+1}}dy.
\end{equation}
In view of our definition of $\epsilon_j$, we have $\mathbf{R}=\sum_j{T}_j$ and $\int_{\epsilon_{j+1}<|y|<\epsilon_j} z|y|^{-z-1}dy=0$ for each $j$. Note that this definition is essentially the same as that in (\ref{Def-Tj}). Let $S_j$ be defined as in (\ref{Def-Sj}) with $\gamma_y(t,x)=(t+S(x,x-y),x-y)$.
Without loss of generality, assume $S(x,x)=0$. Define $R_j=S_{j+1}-S_j$. Then $T_j=T_jS_j+\sum_{k\geq 0} T_j R_{j+k}$. By the same argument as in \cite{Christ-Nagel-Stein-Wainger}, we can show that the following statements are true.
\vspace{0.5\baselineskip}

\noindent (i) $\|\sum_{j\geq 0}T_{j}R_{j+k}\|_{L^2\rightarrow L^2}
\lesssim 2^{-\delta k}$ for some $\delta>0$.\\
\noindent (ii) For each $1<p<2$, $\|\sum_{j\geq 0}T_{j}R_{j+k}\|_{L^p\rightarrow L^p}
\lesssim_{p,\rho} 2^{\rho k}$ for every $\rho>0$.\\
\noindent (iii) For each $1<p\leq 2$, $\|\sum_{j\geq 0}T_{j}S_j\|_{L^p\rightarrow L^p}
\lesssim_{p} 1$.
\vspace{0.5\baselineskip}

\noindent Hence $\mathbf{R}$ is bounded on $L^p$ for every $1<p\leq 2$. By duality, this is also true for $2\leq p <\infty$. By a similar argument as in \cite{Christ-Nagel-Stein-Wainger}, we see that $\mathbf{M}$ is bounded on $L^p$ for $1<p<\infty$.

The boundedness of $\mathbf{R}^{\ast}$ on $L^p$ follows from Theorem \ref{Thm-Maximal-RT} and its proof. The argument in our proof of Theorem \ref{Thm-Maximal-RT} also holds. A slight modification is that $T_j$ in (\ref{Def-Tj}) should be replaced by (\ref{Def-Tj-II}) as above.

\label{Thm-SRT-Semi-Transaltion-inva}
Assume $S$ is a real-valued and real analytic function near the origin in $\Bbb R^2$, and its Hessian can be written as
\begin{equation*}
S''_{xy}(x,y)=U(x,y)\prod_{i=1}^{N}(x-r_i(y)),
\end{equation*}
where $U(x,y)\neq0$ is real analytic near the origin, $r_i$ are convergent Puiseux series in $(-\epsilon,\epsilon)$ with $\epsilon>0$ small enough, $r_i(0)=0$, and $r_i'(0)=1$. Let $\mathbf{R}$ be defined by
\begin{eqnarray*}
\mathbf{R}f(t,x)
=\left(z+\frac{1}{N}\right)
\int_{\Bbb R}f(t+S(x,y),y)
{\prod_{k=1}^{N}|x-r_i(y)|^{Nz}}\varphi(t,x,y)dy,
~~~\,{\rm Re}\,(z)=-\frac1N,
\end{eqnarray*}
where $\varphi\in C_0^{\infty}(\mathbb{R}^3)$ is supported in a small neighborhood of the origin in $\Bbb R^3$. Then $\mathbf{R}$ is bounded on $L^p(\Bbb R^2)$ for $1<p<\infty$.

The statements (ii) and (iii) in Theorem \ref{Main-Thm-2} are contained in Theorem \ref{Thm-Regularity-Unbouned-Faces}. Now assume $(m,n)$ lies on the boundary of $N_r(S)$ and $A_L<m<A_R$, and it is not an extreme point of $N_r(S)$. This assumption implies that $N_r(S)$ has at least two extreme points. By duality, we also assume $m>n$. The case $m=n$ is proved in Phong and Stein \cite{PS1997}; see Theorem \ref{THM-PS-L2-Regularity}.
\vspace{0.5 \baselineskip}

\noindent {\bf Case 1. $S$ is not almost translation invariant.}
\vspace{0.5 \baselineskip}

Assume $(m,n)$ lies on the bounded face with endpoints $(A_{k-1},B_{k-1})$ and $(A_k,B_k)$. Then there exists a $\theta\in (0,1)$ such that $(m,n)=\theta(A_{k-1},B_{k-1})+(1-\theta)(A_k,B_k)$. Consider
\begin{equation*}
\mathbf{R}_zf(t,x)
=
\int_{\Bbb R}f(t+S(x,y),y)
|S''_{xy}(x,y)|^z\varphi(t,x,y)dy,
~~~-\frac{1}{m+n-2}\leq \,{\rm Re}\,(z) \leq \frac{1}{2}.
\end{equation*}
For $z$ on the left line $\,{\rm Re}\,(z)=-\frac{1}{m+n-2}$, $R_z$ is bounded on $L^{p_{\theta}}(\mathbb{R}^2)$ with $p_{\theta}=\frac{m+n-2}{m-1}$. On the other hand, for $z$ with real part $\,{\rm Re}\,(z)=\frac12$, it follows from Theorem \ref{Thm-L2-Damped-RT-Hessian} that $R_z$ is bounded from $L^2$ into $L^2_{1/2}$. By a complex interpolation argument, we have that $R=R_0$ is bounded from $L^p$ into $L^p_{1/(m+n)}$ with $p=\frac{m+n}{m}$.
\vspace{0.5 \baselineskip}

\noindent {\bf Case 2. $S$ is almost translation invariant.}
\vspace{0.5 \baselineskip}

Assume the Hessian $S''_{xy}$ is of the form
\begin{equation*}
S''_{xy}(x,y)=U(x,y)\prod_{i=1}^{N}(x-r_i(y)),
\end{equation*}
where $U(x,y)\neq0$ near the origin, and $r_i$ are convergent Puiseux series satisfying $r_i(0)=0$ and $r_i'(0)=c$ for some real number $c\neq 0$. By dilation, assume $c=1$. By our assumption, we have $1<m<N+1$ and $m+n=N+2$. Consider
\begin{equation*}
\mathbf{R}_zf(t,x)
=
\left(z+\frac{1}{N}\right)
\int_{\Bbb R}f(t+S(x,y),y)
\prod_{i=1}^{N}|(x-r_i(y))|^z\varphi(t,x,y)dy,
\end{equation*}
where $z$ lies on the strip $-\frac{1}{N}\leq \,{\rm Re}\,(z) \leq \frac{1}{2}$. A similar argument as in Case 1, we are able to show that $R=R_0$ is bounded from $L^p(\mathbb{R}^2)$ into $L^p_{1/(N+2)}(\mathbb{R}^2)$ for all $\frac{N+2}{N+1}<p<N+2$.
